@import url("https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap");

ul,ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img,svg,video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button,input,select,textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote,figure,fieldset{margin:revert;padding:revert}
h1,h2,h3,h4,h5,h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}



/* The shared stylesheet, inlined so the page needs no external file.
   The identical copy in site.css is what the CMS should carry globally. */
/* ==========================================================================
   PRIME EXTERIORS - home page stylesheet
   Theme: "Proof of Transformation", image led, high contrast, angled bands.
   Paste into the container / page CSS. Markup lives in prime-exteriors-home.html.
   Fonts: Archivo (headings) + Inter (body).
   ========================================================================== */

:root{
  --navy:#0E2733;
  --char:#1B333F;
  --deep:#0A1C25;
  --aqua:#00B2C9;
  --aqua-ink:#06707F;
  --aqua-lite:#5FD6E4;
  --amber:#F6A117;
  --amber-press:#DC8A05;
  --sand:#EFE8DD;
  --page:#F8FAFB;
  --ink:#22323C;
  --slate:#64767F;
  --line:#DCE3E6;
  --line-dk:rgba(239,232,221,.16);
  --ondark:#D7E2E7;
  --ondark-mute:#9FB2BB;
  --fh:Archivo,"Barlow Semi Condensed","Helvetica Neue",Arial,sans-serif;
  --fb:Inter,"Source Sans 3","Helvetica Neue",Arial,sans-serif;
  --max:1200px;
  --gut:24px;
  --r:10px;
  --rc:14px;
  --sh:0 4px 24px rgba(14,39,51,.08);
  --sh-lift:0 22px 60px rgba(10,28,37,.22);
}

*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--page);color:var(--ink);
  font:400 18px/1.65 var(--fb);-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{max-width:100%;display:block;height:auto}
h1,h2,h3,h4{margin:0;font-family:var(--fh);color:var(--navy);letter-spacing:-.02em;line-height:1.08}
p{margin:0}
ul,ol{margin:0;padding:0;list-style:none}
a{color:var(--aqua-ink);text-decoration:none}
a:hover{text-decoration:underline}
svg{width:18px;height:18px;flex-shrink:0}
:focus-visible{outline:3px solid var(--aqua);outline-offset:3px;border-radius:2px}
.px-wrap,.pe-wrap{max-width:var(--max);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.px-sr,.pe-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.pe-skip{position:absolute;left:8px;top:8px;z-index:300;background:var(--amber);color:var(--navy);
  padding:14px 20px;font:600 15px var(--fb);border-radius:var(--r);
  width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.pe-skip:focus{width:auto;height:auto;overflow:visible;clip:auto}
[hidden]{display:none!important}

/* ---- entrance motion (pure CSS, works with scripts stripped) -------------- */
.px-rise{animation:pxRise .85s cubic-bezier(.22,.61,.36,1) both}
.px-d1{animation-delay:.09s}.px-d2{animation-delay:.18s}.px-d3{animation-delay:.27s}
@keyframes pxRise{from{opacity:0;transform:translate3d(0,30px,0)}to{opacity:1;transform:none}}

/* ---- type ---------------------------------------------------------------- */
.px-h2{font-size:clamp(30px,3.6vw,48px);font-weight:800;text-transform:uppercase;
  letter-spacing:-.015em;line-height:1.04}
.px-h3{font-size:23px;font-weight:700;line-height:1.18;letter-spacing:-.01em}
.px-lede{font-size:21px;line-height:1.6;max-width:68ch;color:var(--slate);margin-top:20px}
.px-eyebrow{display:flex;align-items:center;gap:12px;margin:0 0 16px;
  font:600 13px/1 var(--fh);letter-spacing:.14em;text-transform:uppercase;color:var(--aqua-ink)}
.px-eyebrow::before{content:"";width:34px;height:3px;background:var(--aqua);flex:0 0 34px;
  transform:skewX(-20deg)}
.px-eyebrow--dark{color:var(--aqua-lite)}
.px-head{max-width:800px;margin:0 0 60px}
.px-head--mid{margin-left:auto;margin-right:auto;text-align:center}
.px-head--mid .px-eyebrow{justify-content:center}
.px-head--mid .px-lede{margin-left:auto;margin-right:auto}

.px-go{display:inline-flex;align-items:center;gap:9px;margin-top:20px;
  font:700 14px/1 var(--fh);letter-spacing:.06em;text-transform:uppercase;color:var(--aqua-ink)}
.px-go svg{width:12px;height:12px;transition:transform .22s}
.px-go--dark{color:var(--aqua-lite);margin-top:16px}

.px-ticks li{position:relative;padding:8px 0 8px 26px;font-size:16px;line-height:1.55}
.px-ticks li::before{content:"";position:absolute;left:0;top:14px;width:12px;height:2px;
  background:var(--aqua);transform:skewX(-20deg)}

/* ---- buttons: amber is the call to action and nothing else --------------- */
.px-btn,.pe-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  min-height:54px;padding:15px 30px;border:2px solid transparent;border-radius:var(--r);
  font:700 16px/1.2 var(--fh);letter-spacing:.05em;text-transform:uppercase;cursor:pointer;
  white-space:nowrap;text-decoration:none!important;
  transition:background .2s,border-color .2s,color .2s,transform .2s,box-shadow .2s}
.px-btn--cta,.pe-btn--primary{background:var(--amber);border-color:var(--amber);color:var(--navy);
  box-shadow:0 10px 26px rgba(246,161,23,.26)}
.px-btn--cta:hover,.pe-btn--primary:hover{background:var(--amber-press);border-color:var(--amber-press);
  transform:translateY(-2px)}
.px-btn--ondark,.pe-btn--ondark{background:transparent;border-color:rgba(215,226,231,.45);color:#fff}
.px-btn--ondark:hover,.pe-btn--ondark:hover{background:rgba(0,178,201,.14);border-color:var(--aqua);color:#fff}
.px-btn--ghost,.pe-btn--ghost{background:transparent;border-color:var(--navy);color:var(--navy)}
.px-btn--ghost:hover,.pe-btn--ghost:hover{background:var(--navy);color:#fff}
.px-btn--block,.pe-btn--block{width:100%}

/* ==========================================================================
   HEADER
   ========================================================================== */
.pe-head{position:sticky;top:0;z-index:120;background:var(--navy);
  border-bottom:1px solid rgba(239,232,221,.1)}
.pe-head__bar{display:flex;align-items:center;gap:14px;min-height:80px;position:relative}
.pe-brand{display:flex;align-items:center;gap:12px;text-decoration:none!important;flex:0 0 auto}
.pe-brand img{width:48px;height:48px;background:#fff;border-radius:8px;padding:3px}
.pe-brand__name{font:800 20px/1 var(--fh);color:#fff;letter-spacing:-.02em;text-transform:uppercase}
.pe-brand__sub{display:block;margin-top:5px;font:600 10px/1 var(--fh);letter-spacing:.16em;
  text-transform:uppercase;color:var(--aqua-lite)}
.pe-nav{margin-left:auto;margin-right:4px}
.pe-nav__list{display:flex;align-items:center;gap:2px}
.pe-nav__item{position:static}
.pe-nav__link,.pe-nav__btn{display:flex;align-items:center;gap:7px;white-space:nowrap;
  padding:10px 11px;font:600 14px/1.2 var(--fb);color:var(--ondark);background:none;border:0;
  cursor:pointer;border-radius:var(--r);text-decoration:none!important}
.pe-nav__link:hover,.pe-nav__btn:hover{color:#fff;background:rgba(255,255,255,.08)}
.pe-nav__btn svg{width:10px;height:10px;transition:transform .2s}
.pe-nav__btn[aria-expanded="true"] svg{transform:rotate(180deg)}
.pe-head__phone{display:flex;align-items:center;gap:8px;white-space:nowrap;
  font:700 16px/1 var(--fh);color:#fff;text-decoration:none!important;padding:9px 4px}
.pe-head__phone svg{width:15px;height:15px;color:var(--aqua-lite)}
.pe-head__phone:hover{color:var(--aqua-lite);text-decoration:none!important}
.pe-head__bar .pe-btn{min-height:46px;padding:12px 20px;font-size:14px}
.pe-burger{display:none;width:48px;height:48px;align-items:center;justify-content:center;
  background:none;border:1px solid rgba(239,232,221,.28);border-radius:var(--r);cursor:pointer;margin-left:auto}
.pe-burger svg{width:21px;height:21px;color:#fff}
.pe-head__call{display:none;width:48px;height:48px;align-items:center;justify-content:center;
  background:var(--amber);border-radius:var(--r);color:var(--navy);flex:0 0 48px;margin-left:8px;
  text-decoration:none!important}
.pe-head__call svg{width:19px;height:19px}

/* dropdown + mega */
.pe-drop{position:absolute;top:calc(100% + 6px);left:0;min-width:300px;background:var(--char);
  border:1px solid rgba(239,232,221,.12);border-radius:var(--rc);box-shadow:var(--sh-lift);
  padding:10px;display:none;z-index:119}
.pe-nav__btn[aria-expanded="true"]+.pe-drop{display:block}
.pe-drop a{display:block;padding:10px 14px;font:400 15px/1.35 var(--fb);color:var(--ondark);
  border-radius:var(--r);text-decoration:none!important}
.pe-drop a:hover{background:rgba(0,178,201,.16);color:#fff}
.pe-drop__head{padding:10px 14px 6px;font:700 11px/1 var(--fh);letter-spacing:.16em;
  text-transform:uppercase;color:var(--aqua-lite)}
.pe-nav__item--mega{position:static}
.pe-mega{position:absolute;left:0;right:0;top:100%;background:var(--char);
  border-top:2px solid var(--aqua);box-shadow:var(--sh-lift);display:none;z-index:119}
.pe-nav__btn[aria-expanded="true"]+.pe-mega{display:block}
.pe-mega__inner{max-width:var(--max);margin:0 auto;padding:38px var(--gut) 42px;
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) .86fr;gap:32px}
.pe-mega__head{display:block;font:800 12px/1.3 var(--fh);letter-spacing:.1em;text-transform:uppercase;
  color:#fff;padding-bottom:11px;margin-bottom:10px;border-bottom:2px solid var(--aqua);
  text-decoration:none!important}
.pe-mega__head:hover{color:var(--aqua-lite)}
.pe-mega__head--sp{margin-top:26px}
.pe-mega__col ul{margin:0 0 4px}
.pe-mega__col a:not(.pe-mega__head){display:block;padding:6px 8px 6px 0;font:400 14.5px/1.4 var(--fb);
  color:var(--ondark-mute);text-decoration:none!important;transition:color .16s,transform .16s}
.pe-mega__col a:not(.pe-mega__head):hover{color:var(--aqua-lite);transform:translateX(3px)}
.pe-mega__aside{background:rgba(0,178,201,.09);border:1px solid rgba(0,178,201,.26);
  border-radius:var(--rc);padding:26px 24px;align-self:start}
.pe-mega__eyebrow{font:700 12px/1 var(--fh);letter-spacing:.14em;text-transform:uppercase;
  color:var(--aqua-lite);margin:0 0 12px}
.pe-mega__copy{font:400 14.5px/1.6 var(--fb);color:var(--ondark);margin:0 0 18px}
.pe-mega__jrn{list-style:none;margin:0 0 20px;padding:0}
.pe-mega__jrn a{display:block;padding:9px 0 9px 20px;position:relative;font:600 14.5px/1.4 var(--fb);
  color:#fff;text-decoration:none!important}
.pe-mega__jrn a::before{content:"";position:absolute;left:0;top:17px;width:11px;height:2px;
  background:var(--aqua);transform:skewX(-20deg)}
.pe-mega__jrn a:hover{color:var(--aqua-lite)}
.pe-mega__all{display:inline-flex;align-items:center;gap:8px;margin-top:16px;
  font:700 13px/1 var(--fh);letter-spacing:.08em;text-transform:uppercase;color:var(--aqua-lite)}

/* ==========================================================================
   HERO
   ========================================================================== */
.px-hero{position:relative;background:var(--navy);color:var(--ondark);isolation:isolate;
  padding:120px 0 0;overflow:hidden}
.px-hero__bg{position:absolute;inset:0;z-index:-3}
.px-hero__bg img{width:100%;height:100%;object-fit:cover;object-position:60% 45%;
  transform:scale(1.06);animation:pxZoom 18s ease-out forwards}
@keyframes pxZoom{to{transform:scale(1)}}
.px-hero__scrim{position:absolute;inset:0;z-index:-2;
  background:linear-gradient(104deg,rgba(14,39,51,.97) 0%,rgba(14,39,51,.93) 38%,
    rgba(14,39,51,.62) 66%,rgba(10,28,37,.78) 100%)}
.px-hero__grain{position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:repeating-linear-gradient(115deg,rgba(0,178,201,.07) 0 2px,rgba(0,178,201,0) 2px 9px);
  opacity:.5}
.px-hero__grid{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,.88fr);
  gap:56px;align-items:center;padding-bottom:116px}
.px-hero h1{font-size:clamp(38px,5.4vw,72px);font-weight:800;line-height:1.02;letter-spacing:-.025em;
  text-transform:uppercase;color:#fff}
.px-hero h1 em{display:block;font-style:normal;color:var(--aqua-lite)}
.px-hero__lede{margin-top:26px;font-size:19px;line-height:1.7;color:var(--ondark);max-width:56ch}
.px-hero__cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:36px}
.px-hero__art{position:relative}
.px-hero__plate{margin:0;position:relative;border-radius:var(--rc);overflow:hidden;
  aspect-ratio:4/5;box-shadow:0 40px 90px -30px rgba(0,0,0,.75);
  clip-path:polygon(0 0,100% 44px,100% 100%,0 calc(100% - 44px))}
.px-hero__plate img{width:100%;height:100%;object-fit:cover}
.px-hero__art::after{content:"";position:absolute;left:-18px;top:46px;bottom:46px;width:4px;
  background:linear-gradient(180deg,var(--aqua) 0%,rgba(0,178,201,0) 100%)}

/* stat strip */
.px-stats{position:relative;background:rgba(10,28,37,.86);border-top:1px solid rgba(0,178,201,.3);
  backdrop-filter:blur(3px)}
.px-stats__in{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.px-stat{padding:30px 26px;display:flex;flex-direction:column;gap:7px}
.px-stat+.px-stat{border-left:1px solid rgba(239,232,221,.14)}
.px-stat__n{font:800 clamp(32px,3.4vw,46px)/1 var(--fh);letter-spacing:-.02em;color:var(--aqua-lite)}
.px-stat__l{font:400 14.5px/1.5 var(--fb);color:var(--ondark-mute)}

/* ==========================================================================
   SECTIONS
   ========================================================================== */
.px-sec{padding:110px 0;position:relative}
.px-sec--light{background:var(--page)}
.px-sec--sand{background:var(--sand)}
.px-sec--dark{background:var(--navy);color:var(--ondark)}
.px-sec--deep{background:var(--deep);color:var(--ondark)}
.px-sec--dark h2,.px-sec--dark h3,.px-sec--deep h2,.px-sec--deep h3{color:#fff}
.px-sec--dark .px-lede,.px-sec--deep .px-lede{color:var(--ondark)}
.px-sec--sand .px-lede{color:var(--ink)}
/* angled band entry */
.px-cut{margin-top:-64px;padding-top:184px;clip-path:polygon(0 64px,100% 0,100% 100%,0 100%)}

/* ---- credibility rail: cards lift over the hero -------------------------- */
.px-rail{background:var(--page);padding:0 0 10px}
.px-rail__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;
  margin-top:-58px;position:relative;z-index:2}
.px-rail__card{background:var(--char);color:var(--ondark);border-radius:var(--rc);
  padding:32px 30px 30px;position:relative;overflow:hidden;box-shadow:var(--sh-lift)}
.px-rail__card::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--aqua)}
.px-rail__ico{width:44px;height:44px;display:flex;align-items:center;justify-content:center;
  border-radius:10px;background:rgba(0,178,201,.16);color:var(--aqua-lite);margin-bottom:16px}
.px-rail__ico svg{width:22px;height:22px}
.px-rail__t{font:700 19px/1.25 var(--fh);color:#fff;margin-bottom:9px;letter-spacing:-.01em}
.px-rail__card p{font-size:16px;line-height:1.6;color:var(--ondark-mute)}

/* ---- journeys ------------------------------------------------------------ */
.px-jrn{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px}
.px-jrn__card{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);
  border-radius:var(--rc);overflow:hidden;text-decoration:none!important;
  transition:transform .28s cubic-bezier(.22,.61,.36,1),box-shadow .28s,border-color .28s}
.px-jrn__card:hover{transform:translateY(-6px);box-shadow:var(--sh-lift);border-color:var(--aqua)}
.px-jrn__shot{margin:0;position:relative;aspect-ratio:16/10;overflow:hidden}
.px-jrn__shot img{width:100%;height:100%;object-fit:cover;
  transition:transform .8s cubic-bezier(.22,.61,.36,1)}
.px-jrn__card:hover .px-jrn__shot img{transform:scale(1.07)}
.px-jrn__shot::after{content:"";position:absolute;inset:0;
  background:linear-gradient(0deg,rgba(14,39,51,.72) 0%,rgba(14,39,51,0) 60%)}
.px-jrn__tag{position:absolute;left:0;bottom:16px;z-index:2;margin:0;padding:9px 18px 9px 22px;
  background:var(--aqua);color:var(--navy);font:800 11.5px/1 var(--fh);letter-spacing:.14em;
  text-transform:uppercase;clip-path:polygon(0 0,100% 0,calc(100% - 10px) 100%,0 100%)}
.px-jrn__body{padding:28px 26px 26px;display:flex;flex-direction:column;flex:1}
.px-jrn__body h3{margin-bottom:12px}
.px-jrn__body>p{font-size:16.5px;line-height:1.65;color:var(--ink)}
.px-jrn__body .px-ticks{margin-top:18px;padding-top:16px;border-top:1px solid var(--line);flex:1}
.px-jrn__card:hover .px-go svg{transform:translateX(5px)}

.px-chips{margin-top:40px;padding-top:30px;border-top:1px solid var(--line);
  display:flex;flex-wrap:wrap;align-items:center;gap:14px 20px}
.px-chips__t{font:800 12px/1 var(--fh);letter-spacing:.14em;text-transform:uppercase;color:var(--slate)}
.px-chips ul{display:flex;flex-wrap:wrap;gap:10px}
.px-chips a{display:inline-flex;align-items:center;min-height:42px;padding:10px 18px;
  border:1px solid var(--line);border-radius:999px;background:#fff;
  font:600 14.5px/1 var(--fb);color:var(--ink);text-decoration:none!important;
  transition:border-color .18s,color .18s,background .18s}
.px-chips a:hover{border-color:var(--aqua);color:var(--aqua-ink);background:rgba(0,178,201,.07)}

/* ---- conditions ---------------------------------------------------------- */
.px-cond{display:grid;grid-template-columns:minmax(0,.84fr) minmax(0,1.16fr);gap:64px;align-items:start}
.px-cond__art figure{margin:0}
.px-cond__art img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:var(--rc);
  clip-path:polygon(0 36px,100% 0,100% calc(100% - 36px),0 100%)}
.px-cond__list{counter-reset:c}
.px-cond__list li{counter-increment:c;position:relative;padding:28px 0 28px 74px;
  border-bottom:1px solid rgba(239,232,221,.14)}
.px-cond__list li:first-child{padding-top:0}
.px-cond__list li:last-child{border-bottom:0;padding-bottom:0}
.px-cond__list li::before{content:"0" counter(c);position:absolute;left:0;top:26px;
  font:800 26px/1 var(--fh);color:transparent;-webkit-text-stroke:1.5px var(--aqua)}
.px-cond__list li:first-child::before{top:-2px}
.px-cond__list h3{margin-bottom:10px;color:#fff}
.px-cond__list p{font-size:16.5px;line-height:1.7;color:var(--ondark)}

/* ---- service families ---------------------------------------------------- */
.px-fams{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.px-fam{display:flex;flex-direction:column;background:#fff;border:1px solid rgba(14,39,51,.1);
  border-radius:var(--rc);padding:34px 30px 30px;position:relative;overflow:hidden;
  text-decoration:none!important;transition:transform .25s,box-shadow .25s,border-color .25s}
.px-fam::after{content:"";position:absolute;right:-30px;top:-30px;width:90px;height:90px;
  background:rgba(0,178,201,.1);transform:rotate(45deg);transition:background .25s}
.px-fam:hover{transform:translateY(-5px);box-shadow:var(--sh-lift);border-color:var(--aqua)}
.px-fam:hover::after{background:rgba(0,178,201,.24)}
.px-fam__ico{position:relative;z-index:1;width:52px;height:52px;display:flex;align-items:center;
  justify-content:center;border-radius:12px;background:var(--navy);color:var(--aqua-lite);
  margin-bottom:20px;transition:transform .28s}
.px-fam:hover .px-fam__ico{transform:translateY(-3px)}
.px-fam__ico svg{width:26px;height:26px}
.px-fam h3{margin-bottom:11px}
.px-fam>p{font-size:16.5px;line-height:1.65;color:var(--ink)}
.px-fam__subs{margin-top:20px;padding-top:18px;border-top:1px solid rgba(14,39,51,.1);flex:1;
  display:grid;grid-template-columns:1fr 1fr;gap:2px 18px}
.px-fam__subs li{position:relative;padding:7px 0 7px 20px;font-size:15px;line-height:1.45;color:var(--ink)}
.px-fam__subs li::before{content:"";position:absolute;left:0;top:13px;width:10px;height:2px;
  background:var(--aqua);transform:skewX(-20deg)}
.px-fam:hover .px-go svg{transform:translateX(5px)}

/* ---- clean restore protect ----------------------------------------------- */
.px-crp{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.px-crp__step{position:relative;background:var(--char);border:1px solid rgba(239,232,221,.1);
  border-radius:var(--rc);padding:40px 32px 34px;overflow:hidden}
.px-crp__step::before{content:"";position:absolute;left:0;top:0;width:100%;height:4px;background:var(--aqua)}
.px-crp__n{position:absolute;right:18px;top:6px;font:800 110px/1 var(--fh);letter-spacing:-.04em;
  color:transparent;-webkit-text-stroke:2px rgba(0,178,201,.3);pointer-events:none}
.px-crp__step h3{position:relative;font-size:30px;text-transform:uppercase;margin-bottom:14px;color:#fff}
.px-crp__step>p{position:relative;font-size:16.5px;line-height:1.7;color:var(--ondark)}
.px-crp__step .px-ticks{position:relative;margin-top:22px;padding-top:20px;
  border-top:1px solid rgba(239,232,221,.14)}
.px-crp__step .px-ticks li{color:var(--ondark-mute)}

/* ---- commercial ---------------------------------------------------------- */
.px-comm{display:grid;grid-template-columns:minmax(0,1.04fr) minmax(0,.96fr);gap:60px;align-items:start}
.px-comm__list{margin:28px 0 30px;display:grid;grid-template-columns:1fr 1fr;gap:2px 22px}
.px-comm__list li{position:relative;padding:9px 0 9px 24px;font-size:16.5px;color:var(--ondark)}
.px-comm__list li::before{content:"";position:absolute;left:0;top:18px;width:11px;height:2px;
  background:var(--aqua);transform:skewX(-20deg)}
.px-sched{margin:0 0 30px;padding:26px 28px;border-radius:var(--rc);
  background:rgba(0,178,201,.09);border-left:4px solid var(--aqua)}
.px-sched__t{font:800 12px/1 var(--fh);letter-spacing:.14em;text-transform:uppercase;
  color:var(--aqua-lite);margin:0 0 12px}
.px-sched p{font-size:16px;line-height:1.7;color:var(--ondark)}
.px-comm__art{display:grid;gap:20px}
.px-comm__art figure{margin:0;border-radius:var(--rc);overflow:hidden}
.px-comm__art figure:first-child{clip-path:polygon(0 0,100% 34px,100% 100%,0 100%)}
.px-comm__art figure:last-child{margin-left:48px;clip-path:polygon(0 0,100% 0,100% calc(100% - 34px),0 100%)}
.px-comm__art img{width:100%;aspect-ratio:4/3;object-fit:cover;
  transition:transform .8s cubic-bezier(.22,.61,.36,1)}
.px-comm__art figure:hover img{transform:scale(1.06)}
.px-logos{margin-top:70px;padding-top:44px;border-top:1px solid var(--line-dk)}
.px-logos__t{font:800 11.5px/1 var(--fh);letter-spacing:.18em;text-transform:uppercase;
  color:var(--ondark-mute);text-align:center;margin-bottom:26px}
.px-logos__grid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}
.px-logos__grid li{background:#fff;border-radius:var(--r);display:flex;align-items:center;
  justify-content:center;padding:10px 14px;min-height:84px}
.px-logos__grid img{max-height:62px;width:auto;mix-blend-mode:multiply}

/* ---- gallery ------------------------------------------------------------- */
.px-gal{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:210px;gap:18px}
.px-gal figure{margin:0;position:relative;border-radius:var(--rc);overflow:hidden}
.px-gal img{width:100%;height:100%;object-fit:cover;
  transition:transform .8s cubic-bezier(.22,.61,.36,1)}
.px-gal figure:hover img{transform:scale(1.06)}
.px-gal figure:nth-child(1){grid-column:span 2;grid-row:span 2}
.px-gal figure:nth-child(4){grid-column:span 2}
.px-gal .px-gal__cap{position:absolute;left:0;right:0;bottom:0;padding:38px 20px 18px;
  font:800 13px/1.4 var(--fh);letter-spacing:.1em;text-transform:uppercase;color:#fff;
  background:linear-gradient(0deg,rgba(14,39,51,.95) 0%,rgba(14,39,51,.72) 45%,rgba(14,39,51,0) 100%)}

/* ---- reviews ------------------------------------------------------------- */
.px-revs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.px-rev{background:#fff;border-radius:var(--rc);padding:34px 30px;box-shadow:var(--sh);
  border-top:4px solid var(--aqua)}
.px-rev__stars{display:flex;gap:3px;margin-bottom:16px;color:#F0A000}
.px-rev__stars svg{width:16px;height:16px}
.px-rev blockquote{margin:0;font-size:17px;line-height:1.65;color:var(--ink)}
.px-rev__who{margin-top:22px;padding-top:18px;border-top:1px solid var(--line);
  font-size:14.5px;color:var(--slate)}
.px-rev__who strong{display:block;font:800 16px/1.3 var(--fh);color:var(--navy);margin-bottom:3px}
.px-revs__foot{margin-top:30px;text-align:center;font-size:15px;color:var(--slate)}

/* ---- service areas ------------------------------------------------------- */
.px-areas{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:30px}
.px-area h3{font:800 13px/1 var(--fh);letter-spacing:.16em;text-transform:uppercase;
  color:var(--aqua-lite);padding-bottom:14px;margin-bottom:14px;
  border-bottom:2px solid rgba(0,178,201,.35)}
.px-area li{padding:6px 0}
.px-area a{font-size:16.5px;color:var(--ondark);text-decoration:none}
.px-area a:hover{color:var(--aqua-lite)}
.px-areas__foot{margin-top:46px;padding-top:30px;border-top:1px solid var(--line-dk);
  display:flex;flex-wrap:wrap;align-items:center;gap:18px;justify-content:space-between}
.px-areas__foot p{font-size:17px;color:var(--ondark)}

/* ---- quote --------------------------------------------------------------- */
.px-quote{position:relative;background:var(--navy);padding:110px 0;overflow:hidden}
.px-quote__bg{position:absolute;inset:0;
  background:radial-gradient(70% 90% at 12% 0%,rgba(0,178,201,.22) 0%,rgba(0,178,201,0) 60%)}
.px-quote__grid{position:relative;display:grid;grid-template-columns:minmax(0,.94fr) minmax(0,1.06fr);
  gap:60px;align-items:start}
.px-quote h2{color:#fff}
.px-quote .px-lede{color:var(--ondark)}
.px-steps{margin-top:34px;counter-reset:q}
.px-steps li{counter-increment:q;position:relative;padding:0 0 28px 62px}
.px-steps li:last-child{padding-bottom:0}
.px-steps li::before{content:counter(q);position:absolute;left:0;top:0;width:40px;height:40px;
  border-radius:10px;background:rgba(0,178,201,.18);border:1px solid rgba(0,178,201,.45);
  color:var(--aqua-lite);font:800 16px/38px var(--fh);text-align:center}
.px-steps strong{display:block;font:700 17px/1.35 var(--fh);color:#fff;margin-bottom:6px}
.px-steps span{font-size:16px;line-height:1.7;color:var(--ondark)}
.px-form{background:#fff;border-radius:var(--rc);padding:40px 38px;box-shadow:var(--sh-lift)}
.px-form h3{font-size:24px;margin-bottom:7px}
.px-form__sub{font-size:15.5px;line-height:1.6;color:var(--slate);margin-bottom:26px}
.px-field{margin-bottom:18px;min-width:0}
.px-field--row{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.px-field--row>div{min-width:0}
.px-form label{display:block;margin-bottom:8px;font:600 14px/1.3 var(--fb);color:var(--slate)}
.px-form input,.px-form select,.px-form textarea{width:100%;min-width:0;min-height:52px;
  padding:13px 15px;font:400 16px var(--fb);color:var(--ink);background:#fff;
  border:1px solid var(--line);border-radius:var(--r)}
.px-form textarea{min-height:110px;resize:vertical}
.px-form input:focus,.px-form select:focus,.px-form textarea:focus{border-color:var(--aqua);
  outline:2px solid rgba(0,178,201,.25);outline-offset:0}
.px-form__note{margin-top:16px;text-align:center;font-size:15px;color:var(--slate)}
.px-req,.pe-req{color:var(--aqua-ink)}

/* ==========================================================================
   FOOTER
   ========================================================================== */
.pe-foot{background:var(--deep);color:var(--ondark-mute);padding:76px 0 0;font-size:15px;line-height:1.7}
.pe-foot__grid{display:grid;grid-template-columns:1.45fr 1fr 1fr 1fr;gap:44px;padding-bottom:50px}
.pe-foot h4{font:800 12px/1 var(--fh);letter-spacing:.16em;text-transform:uppercase;color:#fff;
  margin-bottom:18px}
.pe-foot ul{list-style:none;margin:0;padding:0}
.pe-foot li{padding:5px 0}
.pe-foot a{color:var(--ondark)}
.pe-foot a:hover{color:var(--aqua-lite)}
.pe-foot__brand{display:flex;align-items:center;gap:13px;margin-bottom:20px}
.pe-foot__brand img{width:46px;height:46px;background:#fff;border-radius:8px;padding:3px}
.pe-foot__brand span{font:800 18px/1 var(--fh);color:#fff;text-transform:uppercase}
.pe-foot__bar{border-top:1px solid var(--line-dk);padding:22px 0;display:flex;flex-wrap:wrap;
  gap:12px 26px;justify-content:space-between;align-items:center;font-size:14px}
.pe-foot__bar ul{display:flex;flex-wrap:wrap;gap:20px;list-style:none;margin:0;padding:0}
.pe-crafted{display:inline-flex;align-items:center;gap:8px;padding:8px 13px;min-height:36px;
  border:1px solid var(--line-dk);border-radius:var(--r);font:400 13px/1.3 var(--fb);
  color:var(--ondark-mute);text-decoration:none!important;transition:border-color .18s,color .18s,background .18s}
.pe-crafted strong{font:800 13px/1.3 var(--fh);color:var(--aqua-lite)}
.pe-crafted svg{width:15px;height:15px;color:var(--aqua-lite);transition:color .18s}
.pe-crafted:hover{border-color:rgba(239,232,221,.4);background:rgba(255,255,255,.05);color:#fff}
.pe-crafted:hover svg{color:var(--amber)}

/* ==========================================================================
   FLOATING QUOTE WIDGET, MOBILE BAR, BACK TO TOP
   ========================================================================== */
.pe-qtab{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:95;
  display:flex;flex-direction:column;align-items:center;gap:10px;background:var(--amber);
  color:var(--navy);border:0;cursor:pointer;padding:22px 12px;
  border-radius:var(--r) 0 0 var(--r);box-shadow:-10px 12px 34px rgba(10,28,37,.45);
  transition:background .2s,padding-right .2s}
.pe-qtab:hover{background:var(--amber-press);padding-right:16px}
.pe-qtab svg{width:19px;height:19px}
.pe-qtab span{writing-mode:vertical-rl;font:800 13px/1 var(--fh);letter-spacing:.12em;text-transform:uppercase}
.pe-qbar{display:none;position:fixed;left:0;right:0;bottom:0;z-index:96;background:var(--navy);
  border-top:1px solid rgba(239,232,221,.14);gap:10px;
  padding:10px var(--gut) calc(10px + env(safe-area-inset-bottom,0px));
  box-shadow:0 -10px 30px rgba(10,28,37,.4)}
.pe-qbar__call,.pe-qbar__cta{flex:1 1 0;display:flex;align-items:center;justify-content:center;gap:9px;
  min-height:52px;border-radius:var(--r);font:800 14px/1 var(--fh);letter-spacing:.06em;
  text-transform:uppercase;text-decoration:none!important;cursor:pointer;border:2px solid transparent}
.pe-qbar__call{background:transparent;border-color:rgba(215,226,231,.45);color:#fff}
.pe-qbar__call svg{width:16px;height:16px}
.pe-qbar__cta{background:var(--amber);color:var(--navy)}
.pe-qscrim{position:fixed;inset:0;z-index:115;background:rgba(10,28,37,.6);opacity:0;transition:opacity .24s}
.pe-qscrim.is-open{opacity:1}
.pe-qpanel{position:fixed;right:0;top:0;bottom:0;z-index:120;width:min(440px,100vw);background:#fff;
  display:flex;flex-direction:column;overflow-y:auto;box-shadow:-24px 0 70px rgba(10,28,37,.5);
  transform:translateX(100%);transition:transform .32s cubic-bezier(.22,.61,.36,1)}
.pe-qpanel.is-open{transform:none}
body.pe-locked{overflow:hidden}
.pe-qpanel__head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;
  padding:28px 28px 22px;background:var(--navy);color:#fff}
.pe-qpanel__head h2{color:#fff;font-size:24px;margin:0;text-transform:uppercase;letter-spacing:-.015em}
.pe-qpanel__eyebrow{font:800 11.5px/1 var(--fh);letter-spacing:.16em;text-transform:uppercase;
  color:var(--aqua-lite);margin:0 0 9px}
.pe-qpanel__x{width:40px;height:40px;flex:0 0 40px;display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.12);border:0;border-radius:var(--r);color:#fff;cursor:pointer}
.pe-qpanel__x:hover{background:rgba(255,255,255,.24)}
.pe-qpanel__x svg{width:17px;height:17px}
.pe-qsteps{display:flex;list-style:none;margin:0;padding:16px 28px;gap:8px;
  border-bottom:1px solid var(--line);background:var(--sand)}
.pe-qsteps li{display:flex;align-items:center;gap:8px;flex:1;font:600 12px/1.3 var(--fb);color:var(--slate)}
.pe-qsteps li span{width:24px;height:24px;flex:0 0 24px;display:flex;align-items:center;
  justify-content:center;border-radius:50%;background:#fff;border:1px solid var(--line);
  font:800 11.5px/1 var(--fh)}
.pe-qsteps li.is-on{color:var(--navy)}
.pe-qsteps li.is-on span{background:var(--aqua-ink);border-color:var(--aqua-ink);color:#fff}
.pe-qsteps li.is-done span{background:var(--navy);border-color:var(--navy);color:#fff}
.pe-qform{padding:26px 28px 32px;display:flex;flex-direction:column;flex:1}
.pe-qstep{border:0;margin:0;padding:0;min-width:0}
.pe-field{margin-bottom:18px;min-width:0}
.pe-field--row{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.pe-field--row>div{min-width:0}
.pe-qform label,.pe-qlabel{display:block;margin-bottom:8px;font:600 14px/1.3 var(--fb);color:var(--slate)}
.pe-qform input[type=text],.pe-qform input[type=tel],.pe-qform input[type=email],
.pe-qform select,.pe-qform textarea{width:100%;min-width:0;min-height:52px;padding:13px 15px;
  font:400 16px var(--fb);color:var(--ink);background:#fff;border:1px solid var(--line);
  border-radius:var(--r)}
.pe-qform textarea{min-height:110px;resize:vertical}
.pe-qform input:focus,.pe-qform select:focus,.pe-qform textarea:focus{border-color:var(--aqua);
  outline:2px solid rgba(0,178,201,.25)}
.pe-qform input.is-bad{border-color:#B4232A}
.pe-qchips{display:flex;flex-wrap:wrap;gap:9px}
.pe-qchips label{margin:0}
.pe-qchips input{position:absolute;opacity:0;width:1px;height:1px}
.pe-qchips span{display:flex;align-items:center;padding:11px 18px;min-height:46px;
  border:1px solid var(--line);border-radius:var(--r);cursor:pointer;font:600 14.5px/1 var(--fb);
  color:var(--ink);transition:border-color .18s,background .18s,color .18s}
.pe-qchips span:hover{border-color:var(--aqua)}
.pe-qchips input:checked+span{background:var(--aqua-ink);border-color:var(--aqua-ink);color:#fff}
.pe-qchips input:focus-visible+span{outline:3px solid var(--aqua);outline-offset:2px}
.pe-qtip{display:flex;gap:12px;margin:20px 0 0;padding:16px 18px;background:var(--sand);
  border-radius:var(--r);font:400 14px/1.6 var(--fb);color:var(--ink)}
.pe-qtip svg{width:17px;height:17px;flex:0 0 17px;margin-top:3px;color:var(--aqua-ink)}
.pe-qnav{display:flex;gap:11px;margin-top:auto;padding-top:28px}
.pe-qnav .pe-btn{flex:1;min-height:50px;padding:13px 18px;font-size:14px}
.pe-qnote{margin:16px 0 0;font:400 13px/1.6 var(--fb);color:var(--slate);text-align:center}
.pe-top{position:fixed;right:22px;bottom:22px;z-index:90;width:48px;height:48px;border:0;
  border-radius:50%;background:var(--navy);color:#fff;cursor:pointer;display:none;
  align-items:center;justify-content:center;box-shadow:var(--sh-lift)}
.pe-top.is-on{display:flex}
.pe-top svg{width:17px;height:17px}

/* ==========================================================================
   RESPONSIVE
   ========================================================================== */
@media (max-width:1300px){
  .pe-nav,.pe-head__phone{display:none}
  .pe-burger{display:flex}
  .pe-nav.is-open{display:block;position:absolute;left:0;right:0;top:100%;background:var(--navy);
    border-bottom:1px solid rgba(239,232,221,.14);box-shadow:var(--sh-lift);
    padding:10px 0 18px;margin:0;max-height:calc(100vh - 80px);overflow-y:auto}
  .pe-nav.is-open .pe-nav__list{flex-direction:column;align-items:stretch;gap:0;
    max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
  .pe-nav.is-open .pe-nav__link,.pe-nav.is-open .pe-nav__btn{width:100%;padding:15px 2px;
    font-size:16px;border-bottom:1px solid rgba(239,232,221,.12);border-radius:0;
    justify-content:space-between}
  .pe-nav.is-open .pe-drop,.pe-nav.is-open .pe-mega{position:static;display:none;border:0;
    box-shadow:none;background:transparent;padding:4px 0 10px 14px;min-width:0;
    border-left:2px solid rgba(0,178,201,.4)}
  .pe-nav.is-open .pe-nav__btn[aria-expanded="true"]+.pe-drop,
  .pe-nav.is-open .pe-nav__btn[aria-expanded="true"]+.pe-mega{display:block}
  .pe-mega__inner{display:block;padding:6px 0 14px;max-width:none}
  .pe-mega__aside{display:none}
}
@media (max-width:1180px){
  .px-hero__grid{grid-template-columns:minmax(0,1fr);gap:46px;padding-bottom:96px}
  .px-hero__art{max-width:520px}
  .px-stats__in{grid-template-columns:1fr 1fr}
  .px-stat:nth-child(3){border-left:0}
  .px-stat:nth-child(n+3){border-top:1px solid rgba(239,232,221,.14)}
  .px-jrn,.px-fams,.px-crp,.px-revs{grid-template-columns:repeat(2,minmax(0,1fr))}
  .px-areas{grid-template-columns:repeat(2,minmax(0,1fr))}
  .px-cond,.px-comm,.px-quote__grid{grid-template-columns:minmax(0,1fr);gap:46px}
  .px-cond__art img{aspect-ratio:16/9}
  .px-comm__art{grid-template-columns:1fr 1fr}
  .px-comm__art figure:last-child{margin-left:0}
  .px-logos__grid{grid-template-columns:repeat(5,1fr);gap:11px}
  .pe-foot__grid{grid-template-columns:1fr 1fr;gap:38px}
}
@media (max-width:900px){
  .px-sec{padding:68px 0}
  .px-cut{margin-top:-40px;padding-top:112px;clip-path:polygon(0 40px,100% 0,100% 100%,0 100%)}
  .px-hero{padding:72px 0 0}
  .px-hero__grid{padding-bottom:70px}
  .px-hero__scrim{background:linear-gradient(180deg,rgba(14,39,51,.94) 0%,rgba(14,39,51,.86) 55%,rgba(10,28,37,.95) 100%)}
  .px-hero__lede{font-size:17.5px}
  .px-hero__cta{display:grid;grid-template-columns:1fr}
  .px-hero__art::after{display:none}
  .px-rail__grid{margin-top:-40px;grid-template-columns:minmax(0,1fr)}
  .px-jrn,.px-fams,.px-crp,.px-revs{grid-template-columns:minmax(0,1fr)}
  .px-head{margin-bottom:38px}
  .px-lede{font-size:18px;margin-top:16px}
  .px-h3{font-size:20px}
  body{font-size:17px}
  .px-gal{grid-template-columns:repeat(2,1fr);grid-auto-rows:170px}
  .px-gal figure:nth-child(1){grid-row:span 1}
  .px-logos__grid{grid-template-columns:repeat(3,1fr)}
  .px-quote{padding:68px 0}
  .px-crp__n{font-size:86px}
  .px-comm__list,.px-fam__subs{grid-template-columns:minmax(0,1fr)}
  .pe-qtab{display:none}
  .pe-qbar{display:flex}
  .pe-foot{padding-bottom:80px}
  .pe-top{bottom:86px}
  .pe-qpanel{width:100vw;top:auto;height:92vh;border-radius:var(--rc) var(--rc) 0 0;
    transform:translateY(100%)}
  .pe-qpanel.is-open{transform:none}
}
@media (max-width:620px){
  :root{--gut:18px}
  .pe-head__bar{min-height:70px}
  .pe-head__bar .pe-btn--primary{display:none}
  .pe-head__call{display:flex}
  .pe-brand img{width:42px;height:42px}
  .pe-brand__name{font-size:17px}
  .pe-brand__sub{display:none}
  .px-stats__in{grid-template-columns:minmax(0,1fr)}
  .px-stat+.px-stat{border-left:0;border-top:1px solid rgba(239,232,221,.14)}
  .px-stat{padding:22px 0}
  .px-areas{grid-template-columns:minmax(0,1fr)}
  .px-gal{grid-template-columns:minmax(0,1fr);grid-auto-rows:210px}
  .px-gal figure:nth-child(1),.px-gal figure:nth-child(4){grid-column:span 1}
  .px-logos__grid{grid-template-columns:repeat(2,1fr)}
  .px-comm__art{grid-template-columns:minmax(0,1fr)}
  .px-form{padding:28px 22px}
  .px-field--row,.pe-field--row{grid-template-columns:minmax(0,1fr)}
  .px-crp__step{padding:32px 24px 28px}
  .px-crp__n{font-size:70px}
  .pe-foot__grid{grid-template-columns:minmax(0,1fr);gap:34px}
  .pe-foot__bar{flex-direction:column;align-items:flex-start;gap:14px}
  .pe-qsteps{padding:14px 18px;gap:6px}
  .pe-qform{padding:22px 18px 28px}
  .pe-qpanel__head{padding:22px 18px 18px}
}
@media (max-width:400px){
  .pe-head__bar{gap:10px}
  .pe-burger,.pe-head__call{width:44px;height:44px;flex-basis:44px}
  .px-h2{font-size:27px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}
  html{scroll-behavior:auto}
  .px-rise{animation:none;opacity:1;transform:none}
  .px-hero__bg img{animation:none;transform:none}
  .px-jrn__card:hover,.px-fam:hover{transform:none}
}

/* location tile in the hero stat strip */
.px-stat--loc{justify-content:center}
.px-stat__ico{width:42px;height:42px;display:flex;align-items:center;justify-content:center;
  border-radius:10px;background:rgba(0,178,201,.16);color:var(--aqua-lite)}
.px-stat__ico svg{width:21px;height:21px}
.px-stat--loc .px-stat__l{font-size:15.5px;color:var(--ondark)}

/* ---- overflow fixes found by the width sweep ------------------------------ */
/* the slow hero zoom scales the photo past the viewport, so clip it at source */
.px-hero__bg{overflow:hidden}
/* eight nav items plus phone and button need the full 1200 container at 1301+ */
@media (min-width:1301px){
  .pe-head__bar{gap:10px}
  .pe-nav{margin-right:0}
  .pe-nav__link,.pe-nav__btn{padding:10px 7px;font-size:13.5px}
  .pe-head__phone{font-size:15px;gap:6px;padding:9px 2px}
  .pe-head__bar .pe-btn{padding:12px 16px;font-size:13px}
}
/* long button labels wrap instead of pushing the page wide on a phone */
@media (max-width:620px){
  .px-btn,.pe-btn{white-space:normal;text-align:center}
  .px-areas__foot{gap:14px}
  .px-areas__foot .px-btn{width:100%}
}
@media (max-width:400px){
  .pe-head__bar{gap:8px}
  .pe-brand{gap:9px}
  .pe-brand img{width:38px;height:38px}
  .pe-brand__name{font-size:15px}
  .pe-burger,.pe-head__call{width:42px;height:42px;flex-basis:42px}
}

/* ==========================================================================
   REFINEMENT PASS
   Headings return to sentence case. Micro labels (eyebrows, tags, column
   heads) stay uppercase because they are labels, not headings.
   Cards get lighter borders, calmer shadows and a single accent gesture each.
   ========================================================================== */

/* ---- sentence case ------------------------------------------------------- */
.px-hero h1{text-transform:none;letter-spacing:-.03em;line-height:1.04}
.px-h2{text-transform:none;letter-spacing:-.028em;font-weight:800;
  font-size:clamp(30px,3.3vw,45px);line-height:1.08}
.px-h3,.px-crp__step h3,.px-rail__t{text-transform:none}
.pe-brand__name,.pe-foot__brand span,.pe-qpanel__head h2{text-transform:none}
.px-btn,.pe-btn{text-transform:none;letter-spacing:.005em;font-weight:700;font-size:16px}
.pe-qbar__call,.pe-qbar__cta{text-transform:none;letter-spacing:.005em;font-size:15.5px}
.pe-qtab span{text-transform:none;letter-spacing:.05em}
.px-go{text-transform:none;letter-spacing:0;font:700 15px/1 var(--fh)}
.px-gal .px-gal__cap{text-transform:none;letter-spacing:0;font:700 16px/1.35 var(--fh)}

/* ---- calmer depth -------------------------------------------------------- */
:root{--sh-card:0 2px 10px rgba(14,39,51,.05);--sh-hover:0 18px 44px rgba(14,39,51,.12)}

/* ---- hero: cleaner, more air --------------------------------------------- */
.px-hero__grain{opacity:.3}
.px-hero::after{content:"";position:absolute;left:0;right:0;bottom:0;height:160px;z-index:-1;
  background:linear-gradient(0deg,rgba(10,28,37,.85) 0%,rgba(10,28,37,0) 100%);pointer-events:none}
.px-hero__lede{font-size:19.5px;line-height:1.72;max-width:54ch}
.px-hero__plate{clip-path:polygon(0 0,100% 30px,100% 100%,0 calc(100% - 30px));
  box-shadow:0 40px 90px -40px rgba(0,0,0,.8)}
.px-hero__art::after{left:-20px;top:40px;bottom:40px;width:3px}

/* ---- stat strip: quieter rules, bigger figures ---------------------------- */
.px-stats{background:rgba(10,28,37,.9);border-top:1px solid rgba(0,178,201,.26)}
.px-stat{padding:34px 28px}
.px-stat+.px-stat{border-left:1px solid rgba(239,232,221,.1)}
.px-stat__n{font-size:clamp(34px,3.6vw,50px);color:#fff}
.px-stat__l{font-size:15px;color:var(--ondark-mute)}
.px-stat--loc .px-stat__ico{background:rgba(0,178,201,.14)}

/* ---- credibility rail ----------------------------------------------------- */
.px-rail__card{background:var(--char);border:1px solid rgba(0,178,201,.18);
  box-shadow:0 20px 48px rgba(10,28,37,.28);padding:34px 32px 32px}
.px-rail__card::before{height:3px;background:linear-gradient(90deg,var(--aqua) 0%,rgba(0,178,201,0) 100%)}
.px-rail__t{font-size:20px;margin-bottom:10px}

/* ---- section heads: a little more breathing room -------------------------- */
.px-head{margin-bottom:56px}
.px-lede{margin-top:22px;line-height:1.65}

/* ---- journey cards -------------------------------------------------------- */
.px-jrn__card{border:1px solid rgba(14,39,51,.1);box-shadow:var(--sh-card)}
.px-jrn__card:hover{box-shadow:var(--sh-hover);border-color:rgba(0,178,201,.55)}
.px-jrn__shot::after{background:linear-gradient(0deg,rgba(14,39,51,.62) 0%,rgba(14,39,51,0) 58%)}
.px-jrn__tag{bottom:18px;padding:8px 16px 8px 20px;font-size:11px;letter-spacing:.12em}
.px-jrn__body{padding:30px 28px 28px}
.px-jrn__body h3{font-size:22px;margin-bottom:13px}
.px-jrn__body>p{color:var(--slate)}
.px-jrn__body .px-ticks{margin-top:20px;padding-top:18px;border-top:1px solid rgba(14,39,51,.09)}

/* ---- conditions: four panels rather than one long list -------------------- */
.px-cond{gap:56px;align-items:start}
.px-cond__list li{padding:26px 28px 26px 30px;border-bottom:0;border-radius:var(--rc);
  background:rgba(255,255,255,.035);border:1px solid rgba(239,232,221,.1);
  transition:background .25s,border-color .25s,transform .25s}
.px-cond__list li+li{margin-top:16px}
.px-cond__list li:first-child{padding-top:26px}
.px-cond__list li:last-child{padding-bottom:26px}
.px-cond__list li:hover{background:rgba(0,178,201,.08);border-color:rgba(0,178,201,.42);
  transform:translateX(4px)}
.px-cond__list li::before{position:static;display:block;margin-bottom:12px;
  font:800 15px/1 var(--fh);letter-spacing:.14em;color:var(--aqua-lite);-webkit-text-stroke:0}
.px-cond__list h3{font-size:21px}
.px-cond__list p{font-size:16px;color:var(--ondark-mute)}

/* ---- service families: one accent gesture, not two ------------------------ */
.px-fam{border:1px solid rgba(14,39,51,.1);box-shadow:var(--sh-card);padding:36px 32px 32px}
.px-fam::after{display:none}
.px-fam::before{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:var(--aqua);
  transform:scaleX(0);transform-origin:left;transition:transform .35s cubic-bezier(.22,.61,.36,1)}
.px-fam:hover::before{transform:scaleX(1)}
.px-fam:hover{box-shadow:var(--sh-hover);border-color:rgba(0,178,201,.5)}
.px-fam__ico{width:50px;height:50px;border-radius:12px;background:rgba(0,178,201,.12);
  color:var(--aqua-ink)}
.px-fam:hover .px-fam__ico{background:var(--navy);color:var(--aqua-lite)}
.px-fam h3{font-size:21px}
.px-fam>p{color:var(--slate)}
.px-fam__subs{border-top:1px solid rgba(14,39,51,.09)}

/* ---- clean restore protect ------------------------------------------------ */
.px-crp__step{background:rgba(255,255,255,.04);border:1px solid rgba(239,232,221,.12);
  padding:42px 34px 36px;transition:background .25s,border-color .25s,transform .25s}
.px-crp__step:hover{background:rgba(0,178,201,.08);border-color:rgba(0,178,201,.42);
  transform:translateY(-4px)}
.px-crp__step::before{background:linear-gradient(90deg,var(--aqua) 0%,rgba(0,178,201,.15) 100%)}
.px-crp__n{right:22px;top:14px;font-size:96px;-webkit-text-stroke:2px rgba(0,178,201,.22)}
.px-crp__step h3{font-size:28px;letter-spacing:-.02em}
.px-crp__step>p{color:var(--ondark-mute)}

/* ---- commercial ----------------------------------------------------------- */
.px-sched{background:rgba(0,178,201,.08);border:1px solid rgba(0,178,201,.26);border-left-width:4px;
  padding:28px 30px}
.px-sched p{color:var(--ondark-mute)}
.px-comm__art figure{box-shadow:0 26px 60px rgba(0,0,0,.4)}
.px-logos__grid li{transition:transform .22s}
.px-logos__grid li:hover{transform:translateY(-3px)}

/* ---- gallery -------------------------------------------------------------- */
.px-gal .px-gal__cap{padding:40px 22px 20px}

/* ---- reviews -------------------------------------------------------------- */
.px-rev{border:1px solid rgba(14,39,51,.08);border-top:3px solid var(--aqua);
  box-shadow:var(--sh-card);padding:36px 32px;transition:transform .25s,box-shadow .25s}
.px-rev:hover{transform:translateY(-4px);box-shadow:var(--sh-hover)}
.px-rev blockquote{font-size:17.5px;line-height:1.7}

/* ---- service areas -------------------------------------------------------- */
.px-area{padding:26px 26px 22px;border-radius:var(--rc);background:rgba(255,255,255,.035);
  border:1px solid rgba(239,232,221,.1);transition:border-color .25s,background .25s}
.px-area:hover{background:rgba(0,178,201,.07);border-color:rgba(0,178,201,.38)}
.px-area h3{border-bottom:1px solid rgba(0,178,201,.3);padding-bottom:12px}
.px-area a{color:var(--ondark-mute)}
.px-area a:hover{color:#fff;text-decoration:none}

/* ---- quote ---------------------------------------------------------------- */
.px-steps li::before{border-radius:12px;font-size:15px;line-height:38px}
.px-steps strong{font-size:18px}
.px-steps span{color:var(--ondark-mute)}
.px-form{padding:42px 40px}
.px-form h3{font-size:25px}

/* ---- responsive touch ups for the refinement pass ------------------------- */
@media (max-width:900px){
  .px-head{margin-bottom:36px}
  .px-hero__lede{font-size:17.5px}
  .px-crp__step h3{font-size:24px}
  .px-crp__n{font-size:80px}
  .px-jrn__body h3,.px-fam h3,.px-cond__list h3{font-size:20px}
  .px-form{padding:30px 24px}
  .px-stat{padding:24px 0}
}
@media (max-width:620px){
  .px-cond__list li{padding:24px 22px}
  .px-area{padding:22px 20px 18px}
  .px-crp__n{font-size:64px}
}

/* ==========================================================================
   BRIGHT PASS
   Fresher, higher contrast. Water aqua carries the page, the dark bands are
   now a brighter teal navy, and the muted sandstone is replaced by a clean
   aqua tint. Band rhythm rebalanced so light dominates and dark is an accent.
   ========================================================================== */
:root{
  --navy:#0B2E40;
  --char:#11415A;
  --deep:#072433;
  --aqua:#00C2DE;
  --aqua-bright:#36E0EC;
  --aqua-ink:#047E8F;
  --aqua-lite:#6FE6F2;
  --sky:#E6F7FB;
  --sky-line:#C3E9F1;
  --amber:#FFAC17;
  --amber-press:#E8930A;
  --page:#FFFFFF;
  --ink:#16323F;
  --slate:#5A7684;
  --line:#DCE7EC;
  --line-dk:rgba(111,230,242,.2);
  --ondark:#DCEFF4;
  --ondark-mute:#A4C4CF;
  --grad:linear-gradient(135deg,var(--aqua) 0%,var(--aqua-bright) 100%);
  --sh-card:0 2px 12px rgba(11,46,64,.06);
  --sh-hover:0 20px 48px rgba(0,194,222,.2);
}
body{background:var(--page)}

/* ---- bands ---------------------------------------------------------------- */
.px-sec--light{background:var(--page)}
.px-sec--sky{background:var(--sky)}
.px-sec--sky .px-lede{color:var(--ink)}
.px-sec--dark{background:linear-gradient(160deg,#0B2E40 0%,#11415A 58%,#0B2E40 100%)}
.px-sec--deep{background:linear-gradient(160deg,#072433 0%,#0B2E40 60%,#072433 100%)}
.px-sec--sand{background:var(--sky)}

/* ---- accents -------------------------------------------------------------- */
.px-eyebrow::before{background:var(--grad);height:4px;width:38px}
.px-eyebrow{color:var(--aqua-ink);font-weight:700}
.px-eyebrow--dark{color:var(--aqua-lite)}
.px-head .px-h2+.px-lede{color:var(--slate)}
.px-sec--dark .px-lede,.px-sec--deep .px-lede{color:var(--ondark)}

/* ---- buttons -------------------------------------------------------------- */
.px-btn--cta,.pe-btn--primary{background:linear-gradient(135deg,#FFBB3C 0%,#F6A117 100%);
  border-color:#F6A117;color:#0B2E40;box-shadow:0 12px 28px rgba(246,161,23,.34)}
.px-btn--cta:hover,.pe-btn--primary:hover{background:linear-gradient(135deg,#FFAC17 0%,#E8930A 100%);
  border-color:#E8930A}
.px-btn--ghost,.pe-btn--ghost{border-color:var(--aqua-ink);color:var(--aqua-ink)}
.px-btn--ghost:hover,.pe-btn--ghost:hover{background:var(--aqua-ink);border-color:var(--aqua-ink);color:#fff}
.px-btn--ondark,.pe-btn--ondark{border-color:rgba(111,230,242,.55);color:#fff}
.px-btn--ondark:hover,.pe-btn--ondark:hover{background:var(--aqua);border-color:var(--aqua);color:#0B2E40}

/* ---- header --------------------------------------------------------------- */
.pe-head{background:linear-gradient(120deg,#0B2E40 0%,#11415A 100%);
  border-bottom:1px solid rgba(111,230,242,.22)}
.pe-brand__sub{color:var(--aqua-lite)}
.pe-nav__link:hover,.pe-nav__btn:hover{background:rgba(0,194,222,.18);color:#fff}
.pe-mega,.pe-drop{background:linear-gradient(150deg,#0B2E40 0%,#11415A 100%)}
.pe-mega{border-top:3px solid var(--aqua)}
.pe-mega__aside{background:rgba(0,194,222,.12);border-color:rgba(111,230,242,.34)}
.pe-drop a:hover{background:rgba(0,194,222,.2)}

/* ---- hero: brighter wash and a live aqua edge ----------------------------- */
.px-hero{background:#0B2E40}
.px-hero__scrim{background:linear-gradient(104deg,rgba(11,46,64,.95) 0%,rgba(11,46,64,.88) 36%,
  rgba(7,36,51,.52) 66%,rgba(7,36,51,.72) 100%)}
.px-hero__grain{opacity:.42;
  background:repeating-linear-gradient(115deg,rgba(54,224,236,.1) 0 2px,rgba(54,224,236,0) 2px 9px)}
.px-hero::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:radial-gradient(60% 70% at 8% 18%,rgba(0,194,222,.28) 0%,rgba(0,194,222,0) 62%)}
.px-hero::after{background:linear-gradient(0deg,rgba(7,36,51,.8) 0%,rgba(7,36,51,0) 100%)}
.px-hero h1 em{color:var(--aqua-bright)}
.px-hero__art::after{background:linear-gradient(180deg,var(--aqua-bright) 0%,rgba(54,224,236,0) 100%);
  width:4px}

/* ---- stat strip ----------------------------------------------------------- */
.px-stats{background:rgba(7,36,51,.82);border-top:2px solid var(--aqua)}
.px-stat+.px-stat{border-left:1px solid rgba(111,230,242,.18)}
.px-stat__n{background:var(--grad);-webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent;color:var(--aqua-bright)}
.px-stat__l{color:var(--ondark)}
.px-stat__ico{background:rgba(0,194,222,.2);color:var(--aqua-bright)}

/* ---- credibility rail: white cards, crisper against the hero -------------- */
.px-rail__card{background:#fff;color:var(--ink);border:1px solid var(--sky-line);
  box-shadow:0 22px 50px rgba(11,46,64,.16)}
.px-rail__card::before{background:var(--grad)}
.px-rail__ico{background:var(--sky);color:var(--aqua-ink)}
.px-rail__t{color:var(--navy)}
.px-rail__card p{color:var(--slate)}

/* ---- journeys ------------------------------------------------------------- */
.px-jrn__card{border-color:var(--line)}
.px-jrn__card:hover{border-color:var(--aqua);box-shadow:var(--sh-hover)}
.px-jrn__tag{background:var(--grad);color:#06303A}
.px-ticks li::before{background:var(--aqua)}
.px-go{color:var(--aqua-ink)}
.px-go--dark{color:var(--aqua-lite)}
.px-chips a:hover{border-color:var(--aqua);color:var(--aqua-ink);background:var(--sky)}

/* ---- conditions (the one dark storytelling band) -------------------------- */
.px-cond__list li{background:rgba(0,194,222,.07);border-color:rgba(111,230,242,.22)}
.px-cond__list li:hover{background:rgba(0,194,222,.15);border-color:var(--aqua)}
.px-cond__list li::before{color:var(--aqua-bright)}
.px-cond__list p{color:var(--ondark)}

/* ---- service families ----------------------------------------------------- */
.px-fam{border-color:var(--line)}
.px-fam::before{background:var(--grad)}
.px-fam:hover{border-color:var(--aqua);box-shadow:var(--sh-hover)}
.px-fam__ico{background:var(--sky);color:var(--aqua-ink)}
.px-fam:hover .px-fam__ico{background:var(--grad);color:#06303A}
.px-fam__subs li::before{background:var(--aqua)}

/* ---- clean restore protect, now on the bright tint ------------------------ */
.px-sec--sky .px-crp__step{background:#fff;border:1px solid var(--sky-line);
  box-shadow:var(--sh-card)}
.px-sec--sky .px-crp__step:hover{background:#fff;border-color:var(--aqua);
  box-shadow:var(--sh-hover);transform:translateY(-4px)}
.px-sec--sky .px-crp__step::before{background:var(--grad)}
.px-sec--sky .px-crp__n{-webkit-text-stroke:2px rgba(0,194,222,.3)}
.px-sec--sky .px-crp__step h3{color:var(--navy)}
.px-sec--sky .px-crp__step>p{color:var(--slate)}
.px-sec--sky .px-crp__step .px-ticks{border-top-color:var(--sky-line)}
.px-sec--sky .px-crp__step .px-ticks li{color:var(--ink)}

/* ---- commercial ----------------------------------------------------------- */
.px-sched{background:rgba(0,194,222,.12);border-color:rgba(111,230,242,.36);
  border-left:4px solid var(--aqua)}
.px-sched__t{color:var(--aqua-lite)}
.px-sched p{color:var(--ondark)}
.px-comm__list li{color:var(--ondark)}
.px-comm__list li::before{background:var(--aqua)}
.px-logos__t{color:var(--ondark-mute)}

/* ---- gallery -------------------------------------------------------------- */
.px-gal .px-gal__cap{background:linear-gradient(0deg,rgba(7,36,51,.95) 0%,rgba(7,36,51,.7) 45%,
  rgba(7,36,51,0) 100%)}

/* ---- reviews -------------------------------------------------------------- */
.px-rev{background:#fff;border:1px solid var(--sky-line);border-top:4px solid transparent;
  border-image:none;position:relative}
.px-rev::before{content:"";position:absolute;left:-1px;right:-1px;top:-1px;height:4px;
  background:var(--grad);border-radius:var(--rc) var(--rc) 0 0}
.px-rev:hover{box-shadow:var(--sh-hover)}
.px-rev__who strong{color:var(--navy)}

/* ---- service areas, now light --------------------------------------------- */
.px-sec--light .px-area{background:var(--sky);border:1px solid var(--sky-line)}
.px-sec--light .px-area:hover{background:#fff;border-color:var(--aqua);box-shadow:var(--sh-card)}
.px-sec--light .px-area h3{color:var(--aqua-ink);border-bottom-color:var(--sky-line)}
.px-sec--light .px-area a{color:var(--ink)}
.px-sec--light .px-area a:hover{color:var(--aqua-ink)}
.px-sec--light .px-areas__foot{border-top-color:var(--line)}
.px-sec--light .px-areas__foot p{color:var(--slate)}

/* ---- quote ---------------------------------------------------------------- */
.px-quote{background:linear-gradient(150deg,#0B2E40 0%,#11415A 55%,#072433 100%)}
.px-quote__bg{background:radial-gradient(60% 80% at 10% 0%,rgba(0,194,222,.3) 0%,rgba(0,194,222,0) 62%)}
.px-steps li::before{background:rgba(0,194,222,.22);border-color:rgba(111,230,242,.5);
  color:var(--aqua-bright)}
.px-steps span{color:var(--ondark)}
.px-form{border-top:4px solid transparent;background:#fff;position:relative}
.px-form::before{content:"";position:absolute;left:0;right:0;top:0;height:5px;background:var(--grad);
  border-radius:var(--rc) var(--rc) 0 0}

/* ---- footer and widgets ---------------------------------------------------- */
.pe-foot{background:linear-gradient(160deg,#072433 0%,#0B2E40 100%)}
.pe-foot a:hover{color:var(--aqua-bright)}
.pe-crafted strong,.pe-crafted svg{color:var(--aqua-lite)}
.pe-qtab{background:linear-gradient(135deg,#FFBB3C 0%,#F6A117 100%);color:#0B2E40}
.pe-qbar{background:linear-gradient(120deg,#0B2E40 0%,#11415A 100%)}
.pe-qbar__cta{background:linear-gradient(135deg,#FFBB3C 0%,#F6A117 100%);color:#0B2E40}
.pe-qpanel__head{background:linear-gradient(135deg,#0B2E40 0%,#11415A 100%)}
.pe-qsteps{background:var(--sky)}
.pe-qsteps li.is-on span{background:var(--aqua-ink);border-color:var(--aqua-ink)}
.pe-qchips input:checked+span{background:var(--aqua-ink);border-color:var(--aqua-ink)}
.pe-qtip{background:var(--sky)}
.pe-top{background:var(--navy)}
.pe-skip{background:var(--amber);color:#0B2E40}

/* ==========================================================================
   HEADER REBUILD: white bar, utility strip above it, hero quote form
   ========================================================================== */

/* ---- utility strip above the header --------------------------------------- */
.px-top{background:linear-gradient(120deg,#0B2E40 0%,#11415A 100%);color:var(--ondark)}
.px-top__in{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:46px;
  flex-wrap:wrap}
.px-top__rating{display:flex;align-items:center;gap:9px;color:var(--ondark);
  text-decoration:none!important;font:400 14px/1 var(--fb);padding:6px 0}
.px-top__rating:hover .px-top__txt{color:#fff}
.px-top__stars{display:flex;gap:2px;color:#FFBB3C}
.px-top__stars svg{width:14px;height:14px}
.px-top__score{font:800 15px/1 var(--fh);color:#fff;letter-spacing:-.01em}
.px-top__txt{color:var(--ondark-mute);transition:color .18s}
.px-top__right{display:flex;align-items:center;gap:10px}
.px-top__phone{display:flex;align-items:center;gap:8px;white-space:nowrap;
  font:700 15px/1 var(--fh);color:#fff;text-decoration:none!important;padding:6px 2px}
.px-top__phone svg{width:14px;height:14px;color:var(--aqua-bright)}
.px-top__phone:hover{color:var(--aqua-bright)}
.px-top__cta{display:inline-flex;align-items:center;min-height:34px;padding:8px 16px;
  border-radius:8px;background:linear-gradient(135deg,#FFBB3C 0%,#F6A117 100%);color:#0B2E40;
  font:700 13.5px/1 var(--fh);letter-spacing:.01em;text-decoration:none!important;
  transition:filter .18s,transform .18s}
.px-top__cta:hover{filter:brightness(1.06);transform:translateY(-1px)}

/* ---- header on white ------------------------------------------------------ */
.pe-head{background:#fff;border-bottom:1px solid var(--line);box-shadow:0 1px 0 rgba(11,46,64,.04)}
.pe-brand img{background:transparent;padding:0;border-radius:0}
.pe-brand__name{color:var(--navy)}
.pe-brand__sub{color:var(--slate)}
.pe-nav__link,.pe-nav__btn{color:var(--ink)}
.pe-nav__link:hover,.pe-nav__btn:hover{color:var(--aqua-ink);background:var(--sky)}
.pe-nav__btn[aria-expanded="true"]{color:var(--aqua-ink);background:var(--sky)}
.pe-head__phone{color:var(--navy)}
.pe-head__phone svg{color:var(--aqua-ink)}
.pe-head__phone:hover{color:var(--aqua-ink)}
.pe-burger{border-color:var(--line)}
.pe-burger svg{color:var(--navy)}
.pe-head__call{background:linear-gradient(135deg,#FFBB3C 0%,#F6A117 100%);color:#0B2E40}

/* dropdown and mega on white */
.pe-drop{background:#fff;border:1px solid var(--line);box-shadow:0 24px 60px rgba(11,46,64,.14)}
.pe-drop a{color:var(--ink)}
.pe-drop a:hover{background:var(--sky);color:var(--aqua-ink)}
.pe-drop__head{color:var(--slate)}
.pe-mega{background:#fff;border-top:3px solid var(--aqua);
  border-bottom:1px solid var(--line);box-shadow:0 26px 60px rgba(11,46,64,.14)}
.pe-mega__head{color:var(--navy);border-bottom-color:var(--aqua)}
.pe-mega__head:hover{color:var(--aqua-ink)}
.pe-mega__col a:not(.pe-mega__head){color:var(--slate)}
.pe-mega__col a:not(.pe-mega__head):hover{color:var(--aqua-ink)}
.pe-mega__aside{background:var(--sky);border:1px solid var(--sky-line)}
.pe-mega__eyebrow{color:var(--aqua-ink)}
.pe-mega__copy{color:var(--ink)}
.pe-mega__jrn a{color:var(--navy)}
.pe-mega__jrn a:hover{color:var(--aqua-ink)}
.pe-mega__all{color:var(--aqua-ink)}

/* ---- hero: photograph carries it, no pattern overlay ---------------------- */
.px-hero{padding:92px 0 0}

/* V7-07  The V7 hero photograph is a technician cleaning a paved courtyard,
   framed differently from the V6 driveway shot, so the crop is re-aimed to
   suit it. On a phone the hero is very tall, so the crop moves up and left to
   hold the worker and the spray rather than empty sky. */
.px-hero__bg img{object-position:50% 50%}
@media (max-width:620px){
  .px-hero__bg img{object-position:47% 38%}
}
.px-hero__scrim{background:linear-gradient(100deg,rgba(7,36,51,.95) 0%,rgba(11,46,64,.9) 42%,
  rgba(11,46,64,.72) 72%,rgba(7,36,51,.8) 100%)}
.px-hero__grid{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:56px;
  align-items:center;padding-bottom:104px}
.px-hero h1{font-size:clamp(36px,4.4vw,58px)}
.px-hero__lede{font-size:18px;line-height:1.7;max-width:52ch}

/* ---- hero quote form: glass panel matched to the band -------------------- */
.px-hform{position:relative;border-radius:var(--rc);overflow:hidden;
  background:linear-gradient(155deg,rgba(17,65,90,.92) 0%,rgba(7,36,51,.94) 100%);
  border:1px solid rgba(111,230,242,.34);
  box-shadow:0 34px 80px rgba(3,20,29,.55);backdrop-filter:blur(6px)}
.px-hform::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--grad)}
.px-hform__head{padding:30px 32px 0}
.px-hform__t{font:800 25px/1.15 var(--fh);color:#fff;letter-spacing:-.025em}
.px-hform__sub{margin-top:9px;font-size:14.5px;line-height:1.6;color:var(--ondark-mute)}
.px-hform__body{padding:22px 32px 30px}
.px-hform .px-field{margin-bottom:14px}
.px-hform label{display:block;margin-bottom:7px;font:600 13px/1.3 var(--fb);color:var(--ondark)}
.px-hform input,.px-hform select,.px-hform textarea{width:100%;min-width:0;min-height:48px;
  padding:12px 14px;font:400 15.5px var(--fb);color:#fff;
  background:rgba(255,255,255,.07);border:1px solid rgba(111,230,242,.26);border-radius:var(--r)}
.px-hform textarea{min-height:84px;resize:vertical}
.px-hform input::placeholder,.px-hform textarea::placeholder{color:var(--ondark-mute)}
.px-hform select option{background:#0B2E40;color:#fff}
.px-hform input:focus,.px-hform select:focus,.px-hform textarea:focus{border-color:var(--aqua);
  background:rgba(255,255,255,.12);outline:2px solid rgba(0,194,222,.3);outline-offset:0}
.px-hform .px-req{color:var(--aqua-bright)}
.px-hform .px-btn{margin-top:6px}
.px-hform__note{margin-top:14px;text-align:center;font-size:14px;color:var(--ondark-mute)}
.px-hform__note a{color:var(--aqua-bright)}

/* ---- stats and rail: no more overlap -------------------------------------- */
.px-stats{border-top:2px solid var(--aqua)}
.px-rail{padding:76px 0 0}
.px-rail__grid{margin-top:0}
.px-rail__card{box-shadow:var(--sh-card);border:1px solid var(--sky-line)}
.px-rail__card:hover{box-shadow:var(--sh-hover);border-color:var(--aqua)}

@media (max-width:1180px){
  .px-hero__grid{grid-template-columns:minmax(0,1fr);gap:44px;padding-bottom:84px}
  .px-hform{max-width:620px}
}
@media (max-width:900px){
  .px-top__in{min-height:42px;justify-content:center;gap:10px 18px}
  .px-top__txt{display:none}
  .px-hero{padding:56px 0 0}
  .px-hero__grid{padding-bottom:64px}
  .px-rail{padding:56px 0 0}
  .px-rail__grid{margin-top:0}
  .px-hform__head{padding:26px 22px 0}
  .px-hform__body{padding:20px 22px 26px}
}
@media (max-width:620px){
  .px-top__phone{font-size:14px}
  .px-top__cta{padding:8px 13px;font-size:13px}
  .px-hform .px-field--row{grid-template-columns:minmax(0,1fr);gap:0}
  .px-hform .px-field--row>div{margin-bottom:14px}
}
@media (max-width:400px){
  .px-top__in{gap:8px 12px}
  .px-top__score{font-size:14px}
}

/* the phone now lives in the utility strip, so the sticky bar keeps only the
   nav and the quote button and the nav gets its breathing room back */
.pe-head__phone{display:none!important}
@media (min-width:1301px){
  .pe-nav__link,.pe-nav__btn{padding:10px 11px;font-size:14.5px}
  .pe-head__bar{gap:14px}
  .pe-head__bar .pe-btn{padding:13px 22px;font-size:14px}
}

/* ==========================================================================
   HEADER AND HERO FORM TUNING
   ========================================================================== */

/* ---- 1. larger logo ------------------------------------------------------- */
.pe-brand img{width:56px;height:56px}
.pe-brand{gap:14px}
.pe-head__bar{min-height:84px}
.pe-foot__brand img{width:52px;height:52px}

/* ---- 3. the phone is the loudest thing in the utility strip --------------- */
.px-top__in{min-height:50px}
.px-top__right{gap:0}
.px-top__phone{gap:10px;padding:7px 0;font:800 20px/1 var(--fh);letter-spacing:-.01em;color:#fff}
.px-top__phone svg{width:17px;height:17px;color:var(--aqua-bright)}
.px-top__phone:hover{color:var(--aqua-bright)}

/* ---- 4. hero quote form on white ----------------------------------------- */
.px-hform{background:#fff;border:1px solid var(--sky-line);
  box-shadow:0 34px 80px rgba(3,20,29,.42);backdrop-filter:none}
.px-hform__t{color:var(--navy)}
.px-hform__sub{color:var(--slate)}
.px-hform label{color:var(--slate);font-weight:600}
.px-hform input,.px-hform select,.px-hform textarea{color:var(--ink);background:#fff;
  border:1px solid var(--line)}
.px-hform input::placeholder,.px-hform textarea::placeholder{color:var(--slate)}
.px-hform select option{background:#fff;color:var(--ink)}
.px-hform input:focus,.px-hform select:focus,.px-hform textarea:focus{border-color:var(--aqua);
  background:#fff;outline:2px solid rgba(0,194,222,.26)}
.px-hform .px-req{color:var(--aqua-ink)}
.px-hform__note{color:var(--slate)}
.px-hform__note a{color:var(--aqua-ink)}

@media (max-width:900px){
  .pe-head__bar{min-height:76px}
  .px-top__phone{font-size:18px}
}
@media (max-width:620px){
  .pe-head__bar{min-height:70px}
  .pe-brand img{width:48px;height:48px}
  .px-top__phone{font-size:17px}
}
@media (max-width:400px){
  .pe-brand img{width:44px;height:44px}
  .px-top__phone{font-size:16px}
}

/* ==========================================================================
   HERO FORM FLAG + STATS REBUILD
   ========================================================================== */

/* ---- the top rule is replaced by a vertical flag down the right edge ------ */
.px-hform::before{display:none}
.px-hform{position:relative;padding-right:58px;overflow:hidden}
.px-hform__flag{position:absolute;right:0;top:0;bottom:0;width:58px;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(170deg,var(--aqua) 0%,#0093AD 100%);color:#fff;
  font:800 13px/1 var(--fh);letter-spacing:.18em;text-transform:uppercase;
  writing-mode:vertical-rl;transform:rotate(180deg);text-align:center}
.px-hform__flag::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(135deg,rgba(255,255,255,.16) 0 2px,rgba(255,255,255,0) 2px 9px)}
.px-hform__head{padding:30px 30px 0}
.px-hform__body{padding:22px 30px 30px}

/* ---- stats: four matching panels, one icon treatment --------------------- */
.px-stats{position:relative;background:rgba(7,36,51,.86);border-top:2px solid var(--aqua);
  padding:36px 0 42px}
.px-stats__in{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.px-stat{display:flex;flex-direction:column;align-items:flex-start;gap:0;
  padding:28px 26px 26px;border-radius:var(--rc);
  background:linear-gradient(160deg,rgba(255,255,255,.08) 0%,rgba(255,255,255,.03) 100%);
  border:1px solid rgba(111,230,242,.2);
  transition:border-color .25s,background .25s,transform .25s}
.px-stat+.px-stat{border-left:1px solid rgba(111,230,242,.2)}
.px-stat:hover{border-color:var(--aqua);transform:translateY(-4px);
  background:linear-gradient(160deg,rgba(0,194,222,.16) 0%,rgba(255,255,255,.04) 100%)}
.px-stat__ico{width:46px;height:46px;flex:0 0 46px;display:flex;align-items:center;
  justify-content:center;border-radius:12px;background:var(--grad);color:#06303A;
  margin-bottom:18px;box-shadow:0 8px 20px rgba(0,194,222,.3);transition:transform .25s}
.px-stat__ico svg{width:22px;height:22px}
.px-stat:hover .px-stat__ico{transform:translateY(-2px) scale(1.05)}
.px-stat__n{font:800 clamp(34px,3.6vw,48px)/1 var(--fh);letter-spacing:-.03em;
  background:var(--grad);-webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent;margin-bottom:8px}
.px-stat__l{font:400 15px/1.5 var(--fb);color:var(--ondark)}
.px-stat--loc{justify-content:flex-start}
.px-stat--loc .px-stat__t{font:700 19px/1.4 var(--fh);color:#fff;letter-spacing:-.015em}

@media (max-width:1180px){
  .px-stats__in{grid-template-columns:1fr 1fr}
  .px-stat:nth-child(3){border-left:1px solid rgba(111,230,242,.2)}
  .px-stat:nth-child(n+3){border-top:1px solid rgba(111,230,242,.2)}
}
@media (max-width:900px){
  .px-stats{padding:30px 0 34px}
  .px-stat{padding:24px 22px 22px}
  .px-hform__flag{width:48px;font-size:12px;letter-spacing:.14em}
  .px-hform{padding-right:48px}
  .px-hform__head{padding:26px 22px 0}
  .px-hform__body{padding:20px 22px 26px}
}
@media (max-width:620px){
  .px-stats__in{grid-template-columns:minmax(0,1fr);gap:14px}
  .px-stat,.px-stat+.px-stat{border-left:1px solid rgba(111,230,242,.2);border-top:1px solid rgba(111,230,242,.2)}
  .px-stat{padding:22px 20px;flex-direction:row;align-items:center;gap:16px;flex-wrap:wrap}
  .px-stat__ico{margin-bottom:0}
  .px-stat__n{margin-bottom:0;font-size:36px}
  .px-stat__l{flex:1 1 100%;font-size:14.5px}
  .px-stat--loc .px-stat__t{font-size:17px;flex:1}
}
@media (max-width:400px){
  .px-hform__flag{width:42px;font-size:11px}
  .px-hform{padding-right:42px}
}

/* an earlier rule for the location tile was still winning on specificity and
   flattening it to a plain tint, so all four tiles now share one treatment */
.px-stat--loc .px-stat__ico{background:var(--grad);color:#06303A;
  box-shadow:0 8px 20px rgba(0,194,222,.3)}

/* ==========================================================================
   HERO PROOF ROW, FORM TWEAKS, BULLET ALIGNMENT, FULL WIDTH SERVICE LISTS
   ========================================================================== */

/* ---- 1 + 2 + 3. hero form -------------------------------------------------- */
.px-hform{padding-right:0}
.px-hform__head{padding:32px 32px 0}
.px-hform__body{padding:22px 32px 30px}
.px-hform__t{text-transform:capitalize}
.px-hform__note{margin-top:18px;padding:12px 16px;border-radius:var(--r);
  background:var(--sky);border:1px solid var(--sky-line);
  font:600 15px/1.5 var(--fb);color:var(--navy)}
.px-hform__note a{font:800 16px/1 var(--fh);color:var(--aqua-ink);text-decoration:none;
  border-bottom:2px solid var(--aqua);padding-bottom:1px}
.px-hform__note a:hover{color:var(--navy);border-bottom-color:var(--navy);text-decoration:none}

/* ---- 4. the four proof points sit under the hero buttons ------------------ */
.px-proof{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 32px;
  margin-top:38px;padding-top:30px;border-top:1px solid rgba(111,230,242,.22)}
.px-proof li{display:flex;align-items:center;gap:13px;
  font:500 16px/1.5 var(--fb);color:#fff}
.px-proof__ico{width:30px;height:30px;flex:0 0 30px;display:flex;align-items:center;
  justify-content:center;color:var(--aqua-bright)}
.px-proof__ico svg{width:22px;height:22px}

/* ---- 5. bullet marks centre on the line they sit beside ------------------- */
.px-ticks li,.px-fam__subs li,.px-comm__list li{display:flex;align-items:flex-start;gap:13px;
  padding-left:0;position:static}
.px-ticks li::before,.px-fam__subs li::before,.px-comm__list li::before{
  content:"";position:static;flex:0 0 12px;width:12px;height:2px;
  margin-top:calc((1.55em - 2px) / 2);background:var(--aqua);transform:skewX(-20deg)}
.px-ticks li{padding:8px 0}
.px-fam__subs li{padding:7px 0;line-height:1.5}
.px-comm__list li{padding:9px 0;line-height:1.55}
.px-comm__list li::before{background:var(--aqua)}
.px-jrn__card li,.px-crp__step .px-ticks li{line-height:1.55}
.pe-drop a,.px-chips a{display:flex;align-items:center}
.px-go,.px-rail__ico,.px-fam__ico,.px-why__tick{align-items:center}

/* ---- 6. service family lists run the full width of the card --------------- */
.px-fam__subs{grid-template-columns:minmax(0,1fr);gap:0}

@media (max-width:900px){
  .px-proof{margin-top:30px;padding-top:24px;gap:12px 24px}
  .px-proof li{font-size:15.5px}
  .px-hform__head{padding:26px 22px 0}
  .px-hform__body{padding:20px 22px 26px}
}
@media (max-width:620px){
  .px-proof{grid-template-columns:minmax(0,1fr)}
}

/* ---- footer credit: real Nifty Websites AI mark, no frame ----------------- */
.pe-crafted{border:0;padding:0;min-height:0;background:none;gap:9px}
.pe-crafted:hover{border:0;background:none;color:#fff}
.pe-crafted__ico{width:26px;height:26px;border-radius:6px;flex:0 0 26px;display:block}

/* ==========================================================================
   REVIEWS: rating banner + profile style cards
   ========================================================================== */
.px-revbar{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,1fr) auto;
  gap:32px 40px;align-items:center;padding:34px 38px;margin-bottom:38px;
  border-radius:var(--rc);background:linear-gradient(135deg,#0B2E40 0%,#11415A 60%,#072433 100%);
  box-shadow:0 26px 60px rgba(7,36,51,.28);position:relative;overflow:hidden}
.px-revbar::after{content:"";position:absolute;right:-60px;top:-60px;width:260px;height:260px;
  border-radius:50%;background:radial-gradient(circle,rgba(0,194,222,.26) 0%,rgba(0,194,222,0) 70%);
  pointer-events:none}
.px-revbar__id{display:flex;align-items:center;gap:20px;position:relative;z-index:1}
.px-revbar__mark{width:60px;height:60px;flex:0 0 60px;display:flex;align-items:center;
  justify-content:center;border-radius:16px;background:var(--grad);color:#06303A;
  box-shadow:0 10px 26px rgba(0,194,222,.34)}
.px-revbar__mark svg{width:30px;height:30px}
.px-revbar__id .px-eyebrow{margin-bottom:10px}
.px-revbar h2{color:#fff;font-size:clamp(24px,2.4vw,33px);line-height:1.1}
.px-revbar__meta{position:relative;z-index:1;display:flex;flex-direction:column;gap:12px;
  padding-left:40px;border-left:1px solid rgba(111,230,242,.26)}
.px-revbar__stars{display:flex;gap:4px;color:#FFBB3C}
.px-revbar__stars svg{width:20px;height:20px}
.px-revbar__meta p{font-size:15.5px;line-height:1.65;color:var(--ondark)}
.px-revbar__cta{position:relative;z-index:1;white-space:nowrap}
.px-revbar__cta svg{width:13px;height:13px;transition:transform .22s}
.px-revbar__cta:hover svg{transform:translateX(4px)}

.px-rev{display:flex;flex-direction:column;padding:30px 28px 32px;border-top:1px solid var(--sky-line)}
.px-rev::before{display:none}
.px-rev__head{display:flex;align-items:center;gap:14px;margin-bottom:18px}
.px-rev__avatar{width:48px;height:48px;flex:0 0 48px;display:flex;align-items:center;
  justify-content:center;border-radius:50%;font:800 19px/1 var(--fh);color:#fff}
.px-rev__avatar--aqua{background:linear-gradient(140deg,#00C2DE 0%,#047E8F 100%)}
.px-rev__avatar--navy{background:linear-gradient(140deg,#15587A 0%,#0B2E40 100%)}
.px-rev__avatar--deep{background:linear-gradient(140deg,#0E7F8E 0%,#072433 100%)}
.px-rev__who{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1}
.px-rev__who strong{font:800 17px/1.25 var(--fh);color:var(--navy);letter-spacing:-.01em}
.px-rev__meta{font:400 13.5px/1.45 var(--fb);color:var(--slate)}
.px-rev__badge{width:26px;height:26px;flex:0 0 26px;display:flex;align-items:center;
  justify-content:center;color:var(--aqua-ink)}
.px-rev__badge svg{width:20px;height:20px}
.px-rev .px-rev__stars{margin-bottom:16px}
.px-rev blockquote{margin:0;font-size:16.5px;line-height:1.7;color:var(--ink)}

@media (max-width:1180px){
  .px-revbar{grid-template-columns:minmax(0,1fr) auto;gap:26px 32px;padding:30px 30px}
  .px-revbar__meta{padding-left:0;border-left:0;padding-top:22px;
    border-top:1px solid rgba(111,230,242,.26);grid-column:1 / -1}
}
@media (max-width:900px){
  .px-revbar{grid-template-columns:minmax(0,1fr);text-align:left;padding:28px 24px;margin-bottom:28px}
  .px-revbar__cta{width:100%;justify-content:center}
  .px-revbar__mark{width:52px;height:52px;flex-basis:52px}
  .px-revbar__mark svg{width:26px;height:26px}
}
@media (max-width:620px){
  .px-revbar__id{gap:16px}
  .px-rev{padding:26px 22px 28px}
}

/* the old reviewer block carried a top rule and spacing from the previous
   card layout, which was still drawing a stray line beside the avatar */
.px-rev__who{margin-top:0;padding-top:0;border-top:0;font-size:inherit;color:inherit}
.px-rev__who strong{display:block;margin-bottom:0}

/* the stars and supporting line come out of the banner so the rating headline
   gets the room; the two remaining blocks sit on one row */
.px-revbar{grid-template-columns:minmax(0,1fr) auto;gap:28px 48px;padding:36px 40px}
.px-revbar h2{font-size:clamp(26px,2.9vw,40px)}
.px-revbar__id{gap:24px}
@media (max-width:1180px){
  .px-revbar{grid-template-columns:minmax(0,1fr) auto;padding:32px 32px}
}
@media (max-width:860px){
  .px-revbar{grid-template-columns:minmax(0,1fr);gap:24px;padding:30px 24px}
  .px-revbar__cta{width:100%;justify-content:center}
}

/* the rating banner heading sits on its own line under the label */
.px-revbar__id>div{min-width:0}
.px-revbar h2{font-size:clamp(28px,3.1vw,42px);line-height:1.05;letter-spacing:-.03em;
  color:#fff;white-space:nowrap}
.px-revbar__id .px-eyebrow{margin-bottom:12px;letter-spacing:.16em}
@media (max-width:620px){
  .px-revbar h2{white-space:normal;font-size:28px}
}

/* ==========================================================================
   SERVICE AREAS: region map on the left, area cards on the right
   ========================================================================== */
.px-cover{display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:34px;
  align-items:start}

/* ---- the map panel -------------------------------------------------------- */
.px-map{position:relative;margin:0;width:100%;aspect-ratio:600/640;overflow:hidden;
  border-radius:var(--rc);background:#0B2E40;border:1px solid rgba(111,230,242,.26);
  box-shadow:0 30px 70px rgba(7,36,51,.3)}
.px-map__svg{position:absolute;inset:0;width:100%;height:100%}
.px-map__inset{position:absolute;left:16px;top:16px;width:clamp(76px,18%,108px);
  padding:7px 7px 5px;border-radius:10px;text-align:center;
  background:rgba(7,36,51,.86);border:1px solid rgba(111,230,242,.3)}
.px-map__inset svg{width:100%;height:auto;display:block}
.px-map__inset span{display:block;margin-top:3px;font:800 11px/1 var(--fh);letter-spacing:.24em;
  color:var(--ondark-mute)}
.px-map__brand{position:absolute;right:16px;bottom:16px;display:flex;align-items:center;gap:10px;
  max-width:62%;padding:8px 14px 8px 8px;border-radius:10px;
  background:rgba(7,36,51,.9);border:1px solid var(--aqua);
  box-shadow:0 0 24px rgba(0,194,222,.28)}
.px-map__brand img{width:34px;height:34px;flex:none;border-radius:6px}
.px-map__brand span{font:800 13px/1.15 var(--fh);letter-spacing:.06em;text-transform:uppercase;
  color:#fff;min-width:0}

/* ---- pins ----------------------------------------------------------------- */
.px-pin{position:absolute;z-index:2;display:flex;align-items:center;gap:8px;
  transform:translate(-14px,-100%);text-decoration:none!important}
.px-pin--l{flex-direction:row-reverse;transform:translate(calc(-100% + 14px),-100%)}
.px-pin__drop{position:relative;flex:none;width:28px;height:28px;border-radius:50% 50% 50% 0;
  transform:rotate(-45deg);background:var(--grad);
  box-shadow:0 0 0 3px rgba(7,36,51,.85),0 6px 14px rgba(0,0,0,.45),0 0 18px rgba(0,194,222,.55);
  transition:transform .22s}
.px-pin__dot{position:absolute;inset:8px;border-radius:50%;background:#072433}
.px-pin__name{margin-bottom:22px;padding:4px 10px 3px;border-radius:4px;
  background:rgba(7,36,51,.92);border:1px solid rgba(111,230,242,.3);
  border-left:2px solid var(--aqua);white-space:nowrap;
  font:800 12.5px/1.2 var(--fh);letter-spacing:.08em;text-transform:uppercase;color:#fff;
  transition:border-color .22s,color .22s}
.px-pin--l .px-pin__name{border-left:1px solid rgba(111,230,242,.3);border-right:2px solid var(--aqua)}
.px-pin:hover .px-pin__drop{transform:rotate(-45deg) scale(1.15)}
.px-pin:hover .px-pin__name{color:var(--aqua-bright);border-color:var(--aqua)}

/* ---- area cards ----------------------------------------------------------- */
.px-areacards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.px-areacard{display:flex;flex-direction:column;padding:26px 24px 24px;border-radius:var(--rc);
  background:var(--sky);border:1px solid var(--sky-line);
  transition:border-color .25s,background .25s,box-shadow .25s,transform .25s}
.px-areacard:hover{background:#fff;border-color:var(--aqua);box-shadow:var(--sh-hover);
  transform:translateY(-3px)}
.px-areacard__top{display:flex;align-items:center;gap:12px;padding-bottom:16px;margin-bottom:18px;
  border-bottom:1px solid var(--sky-line)}
.px-areacard__ico{width:34px;height:34px;flex:0 0 34px;display:flex;align-items:center;
  justify-content:center;border-radius:9px;background:var(--grad);color:#06303A}
.px-areacard__ico svg{width:19px;height:19px}
.px-areacard h3{font:800 19px/1.2 var(--fh);color:var(--navy);letter-spacing:-.015em}
.px-areacard__links{display:flex;flex-wrap:wrap;gap:9px}
.px-areacard__links a{display:inline-flex;align-items:center;min-height:38px;padding:9px 15px;
  border-radius:999px;background:#fff;border:1px solid var(--sky-line);
  font:600 14.5px/1 var(--fb);color:var(--ink);text-decoration:none!important;
  transition:border-color .18s,color .18s,background .18s}
.px-areacard__links a:hover{border-color:var(--aqua);color:var(--aqua-ink);background:var(--sky)}

@media (max-width:1180px){
  .px-cover{grid-template-columns:minmax(0,1fr);gap:30px}
  .px-map{max-width:560px;margin-inline:auto}
}
@media (max-width:760px){
  .px-areacards{grid-template-columns:minmax(0,1fr)}
  .px-map__brand span{font-size:11.5px}
}
@media (max-width:420px){
  .px-pin__drop{width:22px;height:22px}
  .px-pin{transform:translate(-11px,-100%)}
  .px-pin--l{transform:translate(calc(-100% + 11px),-100%)}
  .px-pin__name{margin-bottom:16px;padding:3px 7px 2px;font-size:11px}
}

/* the four region panels keep their earlier list style, now sitting two across
   beside the map rather than four across the full width */
.px-areacards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-content:start}
.px-sec--light .px-areacards .px-area{padding:26px 26px 22px}
.px-sec--light .px-areacards .px-area h3{margin-bottom:12px}
@media (max-width:760px){.px-areacards{grid-template-columns:minmax(0,1fr)}}

/* ==========================================================================
   HERO PROOF ROW INLINE + QUOTE SECTION REVAMP
   ========================================================================== */

/* ---- proof points flow inline instead of two fixed halves ---------------- */
.px-proof{display:flex;flex-wrap:wrap;gap:14px 34px;margin-top:34px;padding-top:26px}
.px-proof li{flex:0 1 auto;gap:10px;font:400 16px/1.5 var(--fb);color:var(--ondark-mute)}
.px-proof li strong{font-weight:600;color:#fff}
.px-proof__ico{width:20px;height:20px;flex:0 0 20px;color:var(--aqua-bright)}
.px-proof__ico svg{width:18px;height:18px}

/* ---- quote band ----------------------------------------------------------- */
.px-quote{padding:118px 0}
.px-quote::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(118deg,rgba(54,224,236,.07) 0 2px,rgba(54,224,236,0) 2px 11px);
  opacity:.55}
.px-quote::after{content:"";position:absolute;right:-120px;bottom:-140px;width:460px;height:460px;
  border-radius:50%;pointer-events:none;
  background:radial-gradient(circle,rgba(0,194,222,.2) 0%,rgba(0,194,222,0) 68%)}
.px-quote__grid{grid-template-columns:minmax(0,.98fr) minmax(0,1.02fr);gap:64px;align-items:center}
.px-quote h2{font-size:clamp(30px,3.3vw,45px)}

/* steps become cards with a rail running through them */
.px-steps{position:relative;margin-top:36px}
.px-steps::before{content:"";position:absolute;left:21px;top:16px;bottom:16px;width:2px;
  background:linear-gradient(180deg,var(--aqua) 0%,rgba(0,194,222,.12) 100%)}
.px-steps li{position:relative;padding:20px 24px 20px 66px;border-radius:var(--rc);
  background:rgba(255,255,255,.05);border:1px solid rgba(111,230,242,.18);
  transition:background .25s,border-color .25s,transform .25s}
.px-steps li+li{margin-top:16px}
.px-steps li:last-child{padding-bottom:20px}
.px-steps li:hover{background:rgba(0,194,222,.12);border-color:var(--aqua);transform:translateX(4px)}
.px-steps li::before{left:-21px;top:50%;margin-top:-21px;width:42px;height:42px;border-radius:12px;
  background:linear-gradient(140deg,#0B2E40 0%,#11415A 100%);
  border:1px solid rgba(111,230,242,.45);color:var(--aqua-bright);
  font:800 17px/40px var(--fh);text-align:center;
  box-shadow:0 8px 20px rgba(7,36,51,.5)}
.px-steps li:hover::before{background:var(--grad);color:#06303A;border-color:transparent}
.px-steps strong{font-size:18px;margin-bottom:5px}
.px-steps span{font-size:16px;color:var(--ondark-mute)}

/* the form card gets the same treatment as the hero one */
.px-form{padding:0;overflow:hidden;box-shadow:0 34px 90px rgba(3,20,29,.5)}
.px-form::before{height:5px}
.px-form h3{font-size:26px}
.px-form form{padding:0 40px 38px}
.px-form__head{padding:36px 40px 0}
.px-form .px-field:first-of-type{margin-top:0}
.px-form__note{margin-top:18px;padding:13px 16px;border-radius:var(--r);background:var(--sky);
  border:1px solid var(--sky-line);font:600 15px/1.5 var(--fb);color:var(--navy);text-align:center}
.px-form__note a{font:800 16px/1 var(--fh);color:var(--aqua-ink);text-decoration:none;
  border-bottom:2px solid var(--aqua);padding-bottom:1px}
.px-form__note a:hover{color:var(--navy);border-bottom-color:var(--navy)}

@media (max-width:1180px){
  .px-quote__grid{grid-template-columns:minmax(0,1fr);gap:46px}
}
@media (max-width:900px){
  .px-quote{padding:68px 0}
  .px-proof{gap:12px 24px;margin-top:28px;padding-top:22px}
  .px-proof li{font-size:15.5px;flex:1 1 100%}
  .px-steps li{padding:18px 20px 18px 58px}
  .px-steps li::before{left:-18px;width:38px;height:38px;line-height:36px;margin-top:-19px}
  .px-steps::before{left:19px}
  .px-form__head{padding:28px 24px 0}
  .px-form form{padding:0 24px 28px}
}

/* the quote form has no head wrapper, so the heading and helper line carry
   the horizontal padding themselves now that the card is flush */
.px-form>h3{padding:36px 40px 0}
.px-form>.px-form__sub{padding:0 40px;margin-bottom:24px}
@media (max-width:900px){
  .px-form>h3{padding:28px 24px 0}
  .px-form>.px-form__sub{padding:0 24px}
}

/* the label is one flex child, so the gap never splits a sentence around its
   bolded figure */
.px-proof__t{display:inline}

/* ---- quote band tidy up --------------------------------------------------- */
/* the rail running down behind the three steps comes out */
.px-steps::before{display:none}
/* the form card loses its aqua top edge, same as the hero form */
.px-form::before{display:none}
.px-form{border-top:0}
/* heading matches the hero form */
.px-form>h3{text-transform:capitalize}

/* ==========================================================================
   CTA BANNER ABOVE THE FOOTER
   ========================================================================== */
.px-band{position:relative;isolation:isolate;overflow:hidden;
  padding:132px 0;background:var(--deep);text-align:center}
.px-band__bg{position:absolute;inset:0;z-index:-3;overflow:hidden}
.px-band__bg img{width:100%;height:100%;object-fit:cover;object-position:50% 50%}
.px-band__scrim{position:absolute;inset:0;z-index:-2;
  background:linear-gradient(180deg,rgba(7,36,51,.9) 0%,rgba(11,46,64,.82) 45%,rgba(7,36,51,.94) 100%)}
.px-band::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:radial-gradient(62% 72% at 50% 46%,rgba(0,194,222,.24) 0%,rgba(0,194,222,0) 68%)}
.px-band__in{position:relative;max-width:900px;display:flex;flex-direction:column;align-items:center}
.px-band__in .px-eyebrow{justify-content:center;margin-bottom:20px}
.px-band__h{font:800 clamp(34px,5.2vw,64px)/1.05 var(--fh);letter-spacing:-.03em;color:#fff;
  max-width:18ch}
.px-band__btns{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;margin-top:38px}
.px-band__btns .px-btn{min-height:58px;padding:17px 34px;font-size:17px}

@media (max-width:900px){
  .px-band{padding:76px 0}
  .px-band__btns{margin-top:30px;width:100%;flex-direction:column}
  .px-band__btns .px-btn{width:100%;min-height:54px;font-size:16px}
}

/* ---- CTA banner: copy left, stacked buttons right ------------------------- */
.px-band{padding:92px 0;text-align:left}
.px-band__bg img{object-position:60% 50%}
.px-band__scrim{background:linear-gradient(95deg,rgba(7,36,51,.96) 0%,rgba(7,36,51,.92) 44%,
  rgba(11,46,64,.72) 72%,rgba(7,36,51,.86) 100%)}
.px-band::before{background:radial-gradient(58% 80% at 8% 50%,rgba(0,194,222,.24) 0%,rgba(0,194,222,0) 66%)}
.px-band__in{position:relative;max-width:var(--max);display:grid;
  grid-template-columns:minmax(0,1fr) auto;gap:40px 56px;align-items:center}
.px-band__copy{min-width:0}
.px-band__copy .px-eyebrow{justify-content:flex-start;margin-bottom:18px}
.px-band__h{font:800 clamp(32px,4.4vw,56px)/1.03 var(--fh);letter-spacing:-.03em;color:#fff;max-width:18ch}
.px-band__sub{margin-top:14px;font:800 clamp(20px,2.1vw,27px)/1.2 var(--fh);letter-spacing:-.02em;
  color:#fff}
.px-band__sub em{font-style:normal;color:var(--aqua-bright)}
.px-band__p{margin-top:18px;font-size:17px;line-height:1.7;color:var(--ondark);max-width:60ch}
.px-band__fine{margin-top:20px;padding-top:16px;border-top:1px solid rgba(111,230,242,.2);
  font-size:14.5px;line-height:1.6;color:var(--ondark-mute);max-width:66ch}
.px-band__btns{display:flex;flex-direction:column;gap:14px;width:clamp(260px,24vw,320px);margin-top:0}
.px-band__btns .px-btn{width:100%;min-height:60px;padding:17px 26px;font-size:16.5px}
.px-band__btns .px-btn--cta svg{width:14px;height:14px;transition:transform .22s}
.px-band__btns .px-btn--cta:hover svg{transform:translateX(4px)}
.px-band__btns .px-btn--ondark svg{width:17px;height:17px}

@media (max-width:980px){
  .px-band{padding:70px 0}
  .px-band__in{grid-template-columns:minmax(0,1fr);gap:30px}
  .px-band__btns{width:100%;max-width:420px;flex-direction:column}
}
@media (max-width:620px){
  .px-band__btns{max-width:none}
  .px-band__btns .px-btn{min-height:54px;font-size:16px}
}

/* ---- CTA banner: a teal band so it separates from the navy above and the
   deep navy footer below --------------------------------------------------- */
.px-band{background:#06707F;border-top:3px solid var(--aqua-bright);
  border-bottom:3px solid var(--aqua-bright)}
.px-band__bg img{opacity:.3}
.px-band__scrim{background:linear-gradient(95deg,rgba(6,112,127,.95) 0%,rgba(4,126,143,.9) 46%,
  rgba(0,148,170,.74) 74%,rgba(6,112,127,.9) 100%)}
.px-band::before{background:radial-gradient(60% 82% at 10% 50%,rgba(54,224,236,.3) 0%,rgba(54,224,236,0) 68%)}
.px-band__copy .px-eyebrow{color:#06303A}
.px-band__copy .px-eyebrow::before{background:#06303A}
.px-band__sub em{color:#052830}
.px-band__p{color:rgba(255,255,255,.95)}
.px-band__fine{color:rgba(255,255,255,.8);border-top-color:rgba(255,255,255,.3)}
.px-band__btns .px-btn--ondark{border-color:rgba(255,255,255,.7);color:#fff}
.px-band__btns .px-btn--ondark:hover{background:#06303A;border-color:#06303A;color:#fff}

/* ---- CTA banner: back to a dark overlay, but lighter so the photograph
   actually carries the band and sets it apart from the flat navy sections --- */
.px-band{background:#051822;border-top:2px solid rgba(54,224,236,.55);
  border-bottom:2px solid rgba(54,224,236,.55)}
.px-band__bg img{opacity:1}
.px-band__scrim{background:linear-gradient(95deg,rgba(5,24,34,.88) 0%,rgba(5,24,34,.7) 42%,
  rgba(5,24,34,.4) 72%,rgba(5,24,34,.6) 100%)}
.px-band::before{background:radial-gradient(56% 78% at 8% 48%,rgba(0,194,222,.22) 0%,rgba(0,194,222,0) 68%)}
.px-band__copy .px-eyebrow{color:var(--aqua-bright)}
.px-band__copy .px-eyebrow::before{background:var(--grad)}
.px-band__sub em{color:var(--aqua-bright)}
.px-band__p{color:var(--ondark);text-shadow:0 1px 14px rgba(5,24,34,.6)}
.px-band__h,.px-band__sub{text-shadow:0 2px 20px rgba(5,24,34,.55)}
.px-band__fine{color:var(--ondark-mute);border-top-color:rgba(111,230,242,.26)}
.px-band__btns .px-btn--ondark{border-color:rgba(111,230,242,.6);color:#fff;
  background:rgba(5,24,34,.4)}
.px-band__btns .px-btn--ondark:hover{background:var(--aqua);border-color:var(--aqua);color:#06303A}

/* ---- "or" divider between the submit button and the call line ------------- */
.px-or{display:flex;align-items:center;gap:16px;margin:20px 0 14px}
.px-or::before,.px-or::after{content:"";flex:1;height:1px;background:var(--sky-line)}
.px-or span{font:600 13px/1 var(--fb);letter-spacing:.14em;text-transform:lowercase;
  color:var(--slate)}
.px-hform__note,.px-form__note{margin-top:0}

/* ==========================================================================
   SUB HEADINGS AND SMALL LABELS: sentence case instead of all caps
   ========================================================================== */
.px-eyebrow,
.px-chips__t,
.px-sched__t,
.px-logos__t,
.px-areacard h3,
.px-area h3,
.px-sec--light .px-area h3,
.pe-foot h4,
.pe-mega__head,
.pe-drop__head,
.pe-qpanel__eyebrow,
.pe-brand__sub,
.px-jrn__tag,
.px-revbar .px-eyebrow,
.pe-mega__eyebrow,
.pe-mega__all,
.px-map__brand span{text-transform:capitalize;letter-spacing:.05em}
/* the quote tab reads vertically, so it keeps a touch more tracking */
.pe-qtab span{text-transform:capitalize;letter-spacing:.06em}

/* a later rule for the lede that follows an h2 was overriding the dark band
   colour, so ledes inside a dark section head were rendering slate */
.px-sec--dark .px-head .px-lede,
.px-sec--deep .px-head .px-lede,
.px-quote .px-lede{color:var(--ondark)}

/* ==========================================================================
   QUOTE PANEL: highlight badge and call button
   ========================================================================== */
.pe-qpromo{position:relative;overflow:hidden;margin:20px 28px 4px;padding:22px 22px 20px;
  border-radius:var(--rc);background:linear-gradient(150deg,#0B2E40 0%,#11415A 100%);
  border:1px solid rgba(111,230,242,.26)}
.pe-qpromo::after{content:"";position:absolute;right:-50px;top:-50px;width:170px;height:170px;
  border-radius:50%;pointer-events:none;
  background:radial-gradient(circle,rgba(0,194,222,.3) 0%,rgba(0,194,222,0) 70%)}
.pe-qpromo__eyebrow{position:relative;font:700 11.5px/1 var(--fh);letter-spacing:.12em;
  text-transform:capitalize;color:var(--aqua-bright);margin:0 0 10px}
.pe-qpromo__h{position:relative;font:800 27px/1.05 var(--fh);letter-spacing:-.025em;margin:0;
  background:var(--grad);-webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent}
.pe-qpromo__sub{position:relative;margin:6px 0 0;font:800 14px/1.3 var(--fh);letter-spacing:-.005em;
  color:#fff}
.pe-qpromo__list{position:relative;list-style:none;margin:16px 0 0;padding:16px 0 0;
  border-top:1px solid rgba(111,230,242,.2)}
.pe-qpromo__list li{display:flex;align-items:flex-start;gap:11px;padding:6px 0;
  font:400 14px/1.5 var(--fb);color:var(--ondark)}
.pe-qpromo__tick{width:20px;height:20px;flex:0 0 20px;margin-top:1px;display:flex;
  align-items:center;justify-content:center;border-radius:50%;background:var(--grad);color:#06303A}
.pe-qpromo__tick svg{width:12px;height:12px}
.pe-qpromo__call{position:relative;display:flex;align-items:center;justify-content:center;gap:10px;
  margin-top:18px;min-height:50px;padding:13px 18px;border-radius:var(--r);
  background:rgba(255,255,255,.08);border:1px solid rgba(111,230,242,.5);
  font:800 16px/1 var(--fh);letter-spacing:.01em;color:#fff;text-decoration:none!important;
  transition:background .2s,border-color .2s,color .2s}
.pe-qpromo__call svg{width:17px;height:17px;color:var(--aqua-bright);transition:color .2s}
.pe-qpromo__call:hover{background:var(--aqua);border-color:var(--aqua);color:#06303A}
.pe-qpromo__call:hover svg{color:#06303A}
@media (max-width:520px){
  .pe-qpromo{margin:18px 18px 2px;padding:20px 18px 18px}
  .pe-qpromo__h{font-size:24px}
}

/* the panel is a flex column, so the badge was being shrunk by the form below
   it and clipped; it keeps its own height now */
.pe-qpromo{flex:0 0 auto}
.pe-qpanel__head,.pe-qsteps{flex:0 0 auto}

/* the badge now closes the panel, under the step buttons */
.pe-qpromo{margin:4px 28px 28px}
@media (max-width:520px){.pe-qpromo{margin:2px 18px 24px}}

/* ---- utility strip: bigger handset, shorter rating label ------------------ */
.px-top__phone svg{width:23px;height:23px}
.px-top__phone{gap:11px}
/* the label is short enough to keep on small screens now */
@media (max-width:900px){
  .px-top__txt{display:inline}
  .px-top__phone svg{width:21px;height:21px}
}
@media (max-width:400px){.px-top__phone svg{width:19px;height:19px}}

/* the nav items were all position:static for the full width mega menu, so the
   Commercial dropdown was anchoring to the header bar instead of its own item */
.pe-nav__item{position:relative}
.pe-nav__item--mega{position:static}

/* ---- larger icon tiles + a left edge on the condition cards --------------- */
.px-rail__ico{width:58px;height:58px;flex:0 0 58px;border-radius:14px;margin-bottom:20px}
.px-rail__ico svg{width:30px;height:30px}

.px-fam__ico{width:60px;height:60px;flex:0 0 60px;border-radius:14px;margin-bottom:22px}
.px-fam__ico svg{width:32px;height:32px}

/* the border sits transparent at rest so the card does not jump on hover */
.px-cond__list li{border-left:3px solid transparent;
  transition:background .25s,border-color .25s,transform .25s,border-left-color .25s}
.px-cond__list li:hover{border-left-color:var(--aqua-bright)}

/* ==========================================================================
   SERVICE AREA CARDS: white panels, pinned headings, links with chevrons
   ========================================================================== */
.px-sec--light .px-areacards .px-area{position:relative;overflow:hidden;background:#fff;
  border:1px solid var(--sky-line);border-radius:var(--rc);padding:24px 24px 20px;
  box-shadow:var(--sh-card);transition:border-color .25s,box-shadow .25s,transform .25s}
.px-sec--light .px-areacards .px-area::before{content:"";position:absolute;left:0;right:0;top:0;
  height:3px;background:var(--grad);transform:scaleX(0);transform-origin:left;
  transition:transform .35s cubic-bezier(.22,.61,.36,1)}
.px-sec--light .px-areacards .px-area:hover{background:#fff;border-color:var(--aqua);
  box-shadow:var(--sh-hover);transform:translateY(-3px)}
.px-sec--light .px-areacards .px-area:hover::before{transform:scaleX(1)}

.px-area__head{display:flex;align-items:center;gap:12px;padding-bottom:14px;margin-bottom:6px;
  border-bottom:1px solid var(--sky-line)}
.px-area__pin{width:34px;height:34px;flex:0 0 34px;display:flex;align-items:center;
  justify-content:center;border-radius:10px;background:var(--sky);color:var(--aqua-ink);
  transition:background .25s,color .25s}
.px-area__pin svg{width:18px;height:18px}
.px-area:hover .px-area__pin{background:var(--grad);color:#06303A}
.px-sec--light .px-areacards .px-area h3{font:800 18px/1.2 var(--fh);letter-spacing:-.015em;
  color:var(--navy);border:0;padding:0;margin:0;text-transform:capitalize}

.px-sec--light .px-areacards .px-area li{padding:0}
.px-sec--light .px-areacards .px-area li+li a{border-top:1px solid rgba(195,233,241,.6)}
.px-sec--light .px-areacards .px-area a{display:flex;align-items:center;justify-content:space-between;
  gap:12px;padding:12px 2px;font:500 16px/1.4 var(--fb);color:var(--ink);
  text-decoration:none!important;transition:color .2s,padding-left .2s}
.px-sec--light .px-areacards .px-area a:hover{color:var(--aqua-ink);padding-left:8px}
.px-area__arrow{width:13px;height:13px;flex:0 0 13px;color:var(--sky-line);
  transition:transform .2s,color .2s}
.px-sec--light .px-areacards .px-area a:hover .px-area__arrow{color:var(--aqua);transform:translateX(4px)}

@media (max-width:620px){
  .px-sec--light .px-areacards .px-area{padding:22px 20px 18px}
}

/* the diagonal stripe texture comes off the quote band */
.px-quote::before{display:none}

/* ==========================================================================
   BEFORE & AFTER GALLERY  (.px-bna)
   Draggable comparison slider built on a native <input type="range">, so drag,
   touch, click-to-jump and keyboard arrows all come for free and the control
   is announced correctly by screen readers.
   ========================================================================== */
.px-bna{display:grid;grid-template-columns:minmax(0,1.42fr) minmax(0,1fr);
  gap:26px;align-items:stretch}

/* ---- the comparison card ------------------------------------------------- */
.px-ba{--pos:50%;
  position:relative;margin:0;border-radius:var(--rc);overflow:hidden;
  background:#fff;border:1px solid var(--line);box-shadow:var(--sh-card);isolation:isolate;
  display:flex;flex-direction:column;
  transition:box-shadow .25s,transform .25s,border-color .25s}
.px-ba:hover{box-shadow:var(--sh-lift);transform:translateY(-5px);border-color:var(--aqua)}

.px-ba__box{position:relative;display:block;overflow:hidden;background:var(--navy);
  aspect-ratio:7/5}
.px-ba__box img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}

/* base <img> is the AFTER shot; the BEFORE shot sits on top, clipped to the
   slider position along a slight diagonal that echoes the angled bands */
.px-ba__top{position:absolute;inset:0;z-index:2;
  clip-path:polygon(0 0,calc(var(--pos) + 4%) 0,calc(var(--pos) - 4%) 100%,0 100%);
  transition:clip-path .22s ease-out}

/* the seam is clipped from the SAME polygon as the photo edge, so the line and
   the cut stay locked together at every card size and every slider position */
.px-ba__seam{position:absolute;inset:0;z-index:3;pointer-events:none;
  background:linear-gradient(180deg,var(--aqua-bright,#6FE6F2) 0%,#fff 50%,
    var(--aqua-bright,#6FE6F2) 100%);
  clip-path:polygon(
    calc(var(--pos) + 4% - 2px) 0,
    calc(var(--pos) + 4% + 2px) 0,
    calc(var(--pos) - 4% + 2px) 100%,
    calc(var(--pos) - 4% - 2px) 100%);
  filter:drop-shadow(0 0 7px rgba(111,230,242,.9));
  transition:clip-path .22s ease-out}
.px-ba__knob{position:absolute;top:50%;left:var(--pos);z-index:4;
  width:56px;height:56px;border-radius:50%;transform:translate(-50%,-50%);
  display:grid;place-items:center;pointer-events:none;
  background:rgba(255,255,255,.97);color:#0B2E40;
  box-shadow:0 10px 30px rgba(7,36,51,.45),0 0 0 6px rgba(111,230,242,.26);
  transition:left .22s ease-out,box-shadow .25s,transform .25s}
.px-ba__knob svg{width:23px;height:23px}
.px-ba:hover .px-ba__knob{box-shadow:0 10px 30px rgba(7,36,51,.5),0 0 0 11px rgba(111,230,242,.32)}

/* while the pointer is down the slider must track the finger 1:1 */
.px-ba.is-drag .px-ba__top,
.px-ba.is-drag .px-ba__seam,
.px-ba.is-drag .px-ba__knob{transition:none}
.px-ba.is-drag .px-ba__knob{transform:translate(-50%,-50%) scale(1.06)}

/* ---- the range control sits over the whole photo ------------------------- */
.px-ba__range{position:absolute;inset:0;z-index:5;
  width:100%;height:100%;margin:0;padding:0;border:0;background:transparent;
  -webkit-appearance:none;appearance:none;cursor:ew-resize;touch-action:pan-y}
.px-ba__range::-webkit-slider-runnable-track{background:transparent;border:0;height:100%}
.px-ba__range::-moz-range-track{background:transparent;border:0;height:100%}
.px-ba__range::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;
  width:60px;height:60px;border-radius:50%;background:transparent;border:0;cursor:ew-resize}
.px-ba__range::-moz-range-thumb{width:60px;height:60px;border-radius:50%;
  background:transparent;border:0;cursor:ew-resize}
.px-ba__range:focus{outline:0}
.px-ba__range:focus-visible{outline:3px solid var(--aqua);outline-offset:-3px}
.px-ba__range:focus-visible ~ .px-ba__knob{box-shadow:0 10px 30px rgba(7,36,51,.5),0 0 0 11px rgba(111,230,242,.5)}

/* ---- corner labels + hint ------------------------------------------------ */
.px-ba__tag{position:absolute;bottom:18px;z-index:6;display:inline-flex;align-items:center;
  gap:7px;padding:8px 15px;border-radius:999px;pointer-events:none;
  font:800 11px/1 var(--fh);letter-spacing:.17em;text-transform:uppercase;
  backdrop-filter:blur(6px)}
.px-ba__tag--b{left:18px;background:rgba(255,255,255,.94);color:#0B2E40}
.px-ba__tag--a{right:18px;background:rgba(11,46,64,.84);color:#fff;
  box-shadow:inset 0 0 0 1px rgba(111,230,242,.5)}
.px-ba__tag i{width:7px;height:7px;border-radius:50%;background:var(--aqua);display:block}
.px-ba__tag--b i{background:#9AA68F}

.px-ba__hint{position:absolute;top:18px;left:50%;transform:translateX(-50%);z-index:6;
  display:inline-flex;align-items:center;gap:8px;pointer-events:none;
  padding:8px 16px;border-radius:999px;background:rgba(11,46,64,.74);color:#fff;
  font:700 11px/1 var(--fh);letter-spacing:.14em;text-transform:uppercase;
  backdrop-filter:blur(6px);transition:opacity .3s,transform .3s}
.px-ba__hint svg{width:14px;height:14px}
.px-ba:hover .px-ba__hint,
.px-ba.is-drag .px-ba__hint{opacity:0;transform:translateX(-50%) translateY(-6px)}

/* ---- caption bar --------------------------------------------------------- */
.px-ba__cap{flex:1;display:flex;flex-wrap:wrap;align-items:baseline;align-content:flex-start;
  gap:6px 14px;padding:20px 22px;background:#fff;border-top:3px solid transparent;
  border-image:var(--grad) 1;border-image-slice:1}
.px-ba__cap h3{font:800 19px/1.2 var(--fh);letter-spacing:-.015em;color:var(--navy)}
.px-ba__cap p{font:500 15px/1.5 var(--fb);color:var(--slate);width:100%;margin:0}
.px-ba__meta{display:inline-flex;align-items:center;gap:7px;margin-left:auto;
  font:700 12px/1 var(--fh);letter-spacing:.1em;text-transform:uppercase;color:var(--aqua-ink)}
.px-ba__meta svg{width:14px;height:14px}

/* ---- the aside panel ----------------------------------------------------- */
.px-bna__side{display:flex;flex-direction:column;gap:26px;min-width:0}

.px-bna__note{position:relative;overflow:hidden;border-radius:var(--rc);
  border:1px solid rgba(111,230,242,.26);box-shadow:var(--sh-card);
  flex:1;display:flex;flex-direction:column;
  padding:34px 32px 32px;color:#fff;
  background:linear-gradient(158deg,#0B2E40 0%,#11415A 58%,#072433 100%)}
.px-bna__note::before{content:"";position:absolute;inset:0;
  background-image:radial-gradient(rgba(111,230,242,.17) 1.1px,transparent 1.2px);
  background-size:16px 16px}
.px-bna__note::after{content:"";position:absolute;right:-70px;top:-70px;
  width:210px;height:210px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,194,222,.34) 0%,rgba(0,194,222,0) 70%)}
.px-bna__note > *{position:relative;z-index:1}
.px-bna__note h3{font:800 25px/1.14 var(--fh);letter-spacing:-.02em;color:#fff;margin-bottom:14px}
.px-bna__note p{font:400 16px/1.62 var(--fb);color:var(--ondark);margin-bottom:28px}
.px-bna__note .px-btn{margin-top:26px}

.px-bna__stats{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin-top:auto;
  background:rgba(111,230,242,.2);border-radius:10px;overflow:hidden}
.px-bna__stat{background:rgba(7,36,51,.72);padding:18px 16px}
.px-bna__stat b{display:block;font:800 30px/1 var(--fh);letter-spacing:-.02em;
  background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.px-bna__stat span{display:block;margin-top:7px;font:600 12px/1.35 var(--fh);
  letter-spacing:.09em;text-transform:uppercase;color:var(--ondark-mute)}

/* ---- the three small cards ---------------------------------------------- */
.px-bna__row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;margin-top:26px}
.px-bna__row .px-ba__box{aspect-ratio:4/3}
.px-bna__row .px-ba__knob{width:46px;height:46px}
.px-bna__row .px-ba__knob svg{width:19px;height:19px}
.px-bna__row .px-ba__cap{padding:17px 19px}
.px-bna__row .px-ba__cap h3{font-size:17px}
.px-bna__row .px-ba__cap p{font-size:14px}

/* ---- footer line --------------------------------------------------------- */
.px-bna__foot{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;
  gap:18px 26px;margin-top:38px;padding-top:26px;border-top:1px solid var(--sky-line,#C3E9F1)}
.px-bna__foot p{font:500 16px/1.55 var(--fb);color:var(--slate);max-width:62ch;margin:0}

/* ---- responsive ---------------------------------------------------------- */
@media (max-width:1024px){
  .px-bna{grid-template-columns:minmax(0,1fr)}
  .px-bna__side{flex-direction:row;flex-wrap:wrap}
  .px-bna__note{flex:1 1 100%}
  .px-bna__row{gap:20px}
  .px-bna__row .px-ba__cap{padding:15px 17px}
}
@media (max-width:860px){
  .px-bna__row{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:620px){
  .px-bna__row{grid-template-columns:minmax(0,1fr)}
  .px-ba__box{aspect-ratio:4/3}
  .px-ba__hint{font-size:10px;letter-spacing:.1em;padding:7px 13px}
  .px-ba__tag{bottom:14px;padding:7px 12px;font-size:10px}
  .px-ba__tag--b{left:14px}.px-ba__tag--a{right:14px}
  .px-ba__knob{width:48px;height:48px}
  .px-bna__note{padding:28px 24px 26px}
  .px-bna__foot .px-btn{width:100%}
}
@media (prefers-reduced-motion:reduce){
  .px-ba,.px-ba__top,.px-ba__seam,.px-ba__knob,.px-ba__hint{transition:none!important}
}

/* ==========================================================================
   MOBILE NAV DRAWER - contrast fix
   The header was redesigned to a white bar and the nav links were recoloured
   for it (--ink / --slate), but the open drawer kept its original navy
   background, so the links were dark-on-dark and the nested dropdown links
   were the exact same colour as the panel. The drawer now matches the header.
   ========================================================================== */
@media (max-width:1300px){
  .pe-nav.is-open{background:#fff;border-bottom:1px solid var(--line);
    box-shadow:0 22px 48px rgba(11,46,64,.16)}
  /* pull the list in by the padding we add to the rows, so the hover fill gets
     breathing room without the text shifting off the section's left edge */
  .pe-nav.is-open .pe-nav__list{padding:0 calc(var(--gut) - 12px)}
  .pe-nav.is-open .pe-nav__link,
  .pe-nav.is-open .pe-nav__btn{padding:16px 14px;border-radius:8px;
    border-bottom:1px solid var(--line);color:var(--ink)}
  .pe-nav.is-open .pe-nav__item:last-child .pe-nav__link{border-bottom:0}
  /* a touch darker than --aqua-ink so it clears 4.5:1 on the pale hover fill */
  .pe-nav.is-open .pe-nav__link:hover,
  .pe-nav.is-open .pe-nav__btn:hover,
  .pe-nav.is-open .pe-nav__btn[aria-expanded="true"]{color:#06707F;background:var(--sky)}
  .pe-nav.is-open .pe-drop,
  .pe-nav.is-open .pe-mega{border-left:2px solid var(--aqua);padding-left:16px}
  .pe-nav.is-open .pe-drop a,
  .pe-nav.is-open .pe-mega a{padding:11px 12px;border-radius:8px}
  /* nested dropdown and mega-menu links */
  .pe-nav.is-open .pe-drop a,
  .pe-nav.is-open .pe-mega a{color:var(--ink)}
  .pe-nav.is-open .pe-drop a:hover,
  .pe-nav.is-open .pe-mega a:hover{color:#06707F}
  .pe-nav.is-open .pe-mega h3,
  .pe-nav.is-open .pe-mega h4,
  .pe-nav.is-open .pe-drop h3,
  .pe-nav.is-open .pe-drop h4{color:var(--navy)}
  .pe-nav.is-open .pe-mega p,
  .pe-nav.is-open .pe-drop p,
  .pe-nav.is-open .pe-mega span:not(.px-sr),
  .pe-nav.is-open .pe-drop span:not(.px-sr){color:var(--slate)}
}

/* ==========================================================================
   INTERNAL PAGES - components added for Phase 2 and later
   Added for the approved architecture. No v6 rule above is edited or removed.
   Every value below uses an existing v6 token. On --sky surfaces body text is
   --ink, never --slate or --aqua-ink, because those measure 4.37 and 4.35 on
   that background and only clear AA at large sizes.
   ========================================================================== */

/* ---- current page in the navigation -------------------------------------- */
.pe-nav__link[aria-current="page"],.pe-nav__btn[aria-current="true"]{color:var(--aqua-ink)}
.pe-nav__link[aria-current="page"]::after{transform:scaleX(1)}
.pe-mega__head[aria-current="page"],.pe-mega a[aria-current="page"],
.pe-drop a[aria-current="page"]{color:var(--aqua-ink);font-weight:700}
.pe-foot a[aria-current="page"]{color:#fff}

/* ---- breadcrumb ---------------------------------------------------------- */
.px-crumb{background:var(--sky);border-bottom:1px solid var(--sky-line)}
.px-crumb ol{display:flex;flex-wrap:wrap;align-items:center;gap:7px;
  padding:14px var(--gut);margin:0 auto;list-style:none;
  font:400 14px/1.5 var(--fb);color:var(--ink)}
.px-crumb li{display:flex;align-items:center;gap:7px;min-height:24px}
.px-crumb a{color:var(--aqua-ink);font-weight:600;text-decoration:none;
  padding:3px 0;border-bottom:1px solid transparent;transition:border-color .18s}
.px-crumb a:hover{border-bottom-color:var(--aqua-ink)}
.px-crumb svg{width:11px;height:11px;color:var(--slate);flex:none}
.px-crumb [aria-current="page"]{color:var(--ink);font-weight:400}
@media (max-width:600px){
  .px-crumb ol{font-size:13px;padding:11px var(--gut)}
  .px-crumb li:not(:last-child):not(:first-child){display:none}
}

/* ---- interior hero ------------------------------------------------------- */
.px-ihero{position:relative;background:linear-gradient(160deg,#0B2E40 0%,#11415A 60%,#0B2E40 100%);
  color:var(--ondark);overflow:hidden;isolation:isolate}
.px-ihero__bg{position:absolute;inset:0;z-index:-2}
.px-ihero__bg img{width:100%;height:100%;object-fit:cover;object-position:center}
.px-ihero__scrim{position:absolute;inset:0;z-index:-1;
  background:linear-gradient(100deg,rgba(7,36,51,.95) 0%,rgba(11,46,64,.86) 46%,rgba(11,46,64,.56) 100%)}
.px-ihero__in{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);
  gap:62px;align-items:center;padding:78px var(--gut) 84px}
.px-ihero h1{font:800 clamp(30px,3.5vw,49px)/1.08 var(--fh);letter-spacing:-.022em;color:#fff;margin:0}
.px-ihero h1 em{font-style:normal;color:var(--aqua-lite)}
.px-ihero__lede{font:400 19px/1.68 var(--fb);color:var(--ondark);margin-top:22px;max-width:56ch}
.px-ihero__cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}
.px-ihero__facts{display:flex;flex-wrap:wrap;gap:12px 30px;margin:32px 0 0;padding-top:26px;
  border-top:1px solid var(--line-dk);list-style:none}
.px-ihero__facts li{display:flex;align-items:center;gap:10px;
  font:400 15.5px/1.5 var(--fb);color:var(--ondark-mute)}
.px-ihero__facts svg{width:17px;height:17px;color:var(--aqua-lite);flex:none}
.px-ihero__art{position:relative}
.px-ihero__art figure{margin:0;border-radius:var(--rc);overflow:hidden;
  box-shadow:0 36px 80px -36px rgba(0,0,0,.76);border:1px solid var(--line-dk)}
.px-ihero__art img{display:block;width:100%;height:auto}
@media (max-width:1000px){
  .px-ihero__in{grid-template-columns:minmax(0,1fr);gap:40px;padding:58px var(--gut) 62px}
  .px-ihero__lede{max-width:none}
}
@media (max-width:600px){.px-ihero__in{padding:44px var(--gut) 48px}.px-ihero__lede{font-size:17.5px;margin-top:18px}}

/* ---- answer block -------------------------------------------------------- */
.px-answer{display:grid;grid-template-columns:minmax(0,.4fr) minmax(0,1fr);gap:54px;align-items:start}
.px-answer__k{font:800 13px/1.5 var(--fh);letter-spacing:.14em;text-transform:uppercase;
  color:var(--aqua-ink);margin:0;padding-top:7px}
.px-answer__v{font:400 20px/1.66 var(--fb);color:var(--ink);margin:0}
.px-answer__v strong{font-weight:700;color:var(--navy)}
.px-answer__v+.px-answer__v{margin-top:20px;font-size:17.5px;color:var(--slate)}
@media (max-width:900px){.px-answer{grid-template-columns:minmax(0,1fr);gap:16px}
  .px-answer__v{font-size:18.5px}}

/* ---- prose --------------------------------------------------------------- */
.px-prose{max-width:74ch}
.px-prose p{font:400 17.5px/1.78 var(--fb);color:var(--ink);margin:0 0 22px}
.px-prose p:last-child{margin-bottom:0}
.px-prose h3{font:700 23px/1.22 var(--fh);color:var(--navy);letter-spacing:-.012em;margin:38px 0 14px}
.px-prose h3:first-child{margin-top:0}
.px-prose strong{font-weight:700;color:var(--navy)}
.px-prose a{color:var(--aqua-ink);font-weight:600;border-bottom:1px solid var(--sky-line);
  text-decoration:none;transition:border-color .18s}
.px-prose a:hover{border-bottom-color:var(--aqua-ink)}
.px-sec--dark .px-prose p,.px-sec--deep .px-prose p{color:var(--ondark)}
.px-sec--dark .px-prose h3,.px-sec--deep .px-prose h3{color:#fff}
.px-sec--dark .px-prose strong,.px-sec--deep .px-prose strong{color:#fff}
.px-sec--dark .px-prose a,.px-sec--deep .px-prose a{color:var(--aqua-lite);border-bottom-color:var(--line-dk)}

/* ---- two column scope: what is included, what is not --------------------- */
.px-scope{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}
.px-scope__col{background:#fff;border:1px solid var(--line);border-radius:var(--rc);
  padding:34px 32px;box-shadow:var(--sh-card)}
.px-scope__col--out{background:var(--sky);border-color:var(--sky-line);box-shadow:none}
.px-scope h3{display:flex;align-items:center;gap:12px;
  font:700 20px/1.25 var(--fh);color:var(--navy);margin:0 0 6px}
.px-scope h3 span{display:inline-flex;align-items:center;justify-content:center;
  width:30px;height:30px;border-radius:9px;flex:none}
.px-scope__col h3 span{background:rgba(0,194,222,.13);color:var(--aqua-ink)}
.px-scope__col--out h3 span{background:#fff;color:var(--slate);border:1px solid var(--sky-line)}
.px-scope h3 svg{width:16px;height:16px}
.px-scope__note{font:400 15.5px/1.6 var(--fb);color:var(--slate);margin:0 0 18px}
.px-scope__col--out .px-scope__note{color:var(--ink)}
.px-scope ul{list-style:none;margin:0;padding:0}
.px-scope li{position:relative;padding:10px 0 10px 28px;
  font:400 16.5px/1.6 var(--fb);color:var(--ink);border-top:1px solid var(--line)}
.px-scope__col--out li{border-top-color:var(--sky-line)}
.px-scope li:first-of-type{border-top:0}
.px-scope li::before{content:"";position:absolute;left:3px;top:19px;width:9px;height:9px;
  border-radius:50%;background:var(--aqua)}
.px-scope__col--out li::before{background:none;left:2px;top:17px;width:12px;height:12px;
  border-radius:3px;border:1.5px solid var(--slate)}
@media (max-width:900px){.px-scope{grid-template-columns:minmax(0,1fr)}}
@media (max-width:600px){.px-scope__col{padding:28px 22px}}

/* ---- numbered process ---------------------------------------------------- */
.px-proc{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,232px),1fr));gap:1px;
  background:var(--line);border:1px solid var(--line);border-radius:var(--rc);overflow:hidden}
.px-proc__s{background:#fff;padding:34px 28px 30px;position:relative}
.px-proc__n{display:block;font:800 13px/1 var(--fh);letter-spacing:.16em;
  color:var(--aqua-ink);margin-bottom:18px}
.px-proc__s h3{font:700 19px/1.3 var(--fh);color:var(--navy);margin:0 0 10px;letter-spacing:-.01em}
.px-proc__s p{font:400 16px/1.68 var(--fb);color:var(--slate);margin:0}
.px-proc__s::after{content:"";position:absolute;left:0;top:0;height:3px;width:0;
  background:var(--grad);transition:width .4s cubic-bezier(.22,.61,.36,1)}
.px-proc__s:hover::after{width:100%}
@media (max-width:600px){.px-proc__s{padding:28px 22px 24px}}

/* ---- comparison table ---------------------------------------------------- */
.px-cmp__box{border:1px solid var(--line);border-radius:var(--rc);overflow:hidden;background:#fff}
.px-cmp table{width:100%;border-collapse:collapse}
.px-cmp caption{text-align:center;padding:22px 26px 0;
  font:400 15.5px/1.6 var(--fb);color:var(--slate)}
.px-cmp th,.px-cmp td{padding:17px 22px;text-align:left;vertical-align:top;
  border-top:1px solid var(--line);font:400 16px/1.62 var(--fb);color:var(--ink)}
.px-cmp thead th{background:var(--navy);color:#fff;border-top:0;
  font:700 15px/1.4 var(--fh);letter-spacing:.01em}
.px-cmp tbody th{font:700 16px/1.5 var(--fb);color:var(--navy);width:27%}
.px-cmp tbody tr:nth-child(even) td,.px-cmp tbody tr:nth-child(even) th{background:var(--sky)}
.px-cmp__wrap{overflow-x:auto;-webkit-overflow-scrolling:touch}
@media (max-width:720px){
  .px-cmp table{min-width:560px}
  .px-cmp th,.px-cmp td{padding:14px 16px;font-size:15px}
}

/* ---- factor cards -------------------------------------------------------- */
.px-fact{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,268px),1fr));gap:22px}
.px-fact__c{background:#fff;border:1px solid var(--line);border-left:3px solid var(--aqua);
  border-radius:0 var(--rc) var(--rc) 0;padding:28px 26px}
.px-fact__c h3{font:700 18px/1.3 var(--fh);color:var(--navy);margin:0 0 9px}
.px-fact__c p{font:400 16px/1.68 var(--fb);color:var(--slate);margin:0}
.px-sec--sky .px-fact__c{border-color:var(--sky-line);border-left-color:var(--aqua)}
.px-sec--sky .px-fact__c p{color:var(--ink)}

/* ---- FAQ ----------------------------------------------------------------- */
/* V8-01  The question list was capped at 900px inside a 1152px content
   column, so it sat short of every other block on the page with empty space
   down its right. It now uses the same container width as its neighbours. */
.px-faq{border-top:1px solid var(--line)}
.px-faq details{border-bottom:1px solid var(--line)}
.px-faq summary{display:flex;align-items:flex-start;gap:16px;cursor:pointer;
  padding:24px 0;list-style:none;min-height:24px;
  font:700 18.5px/1.46 var(--fh);color:var(--navy);letter-spacing:-.008em}
.px-faq summary::-webkit-details-marker{display:none}
.px-faq summary .px-faq__m{flex:none;margin-left:auto;position:relative;top:2px;
  width:26px;height:26px;border-radius:7px;background:var(--sky);
  box-shadow:inset 0 0 0 1px var(--sky-line);transition:background .2s}
.px-faq summary .px-faq__m::before,.px-faq summary .px-faq__m::after{content:"";
  position:absolute;left:50%;top:50%;background:var(--aqua-ink);border-radius:1px;
  transform:translate(-50%,-50%);transition:transform .26s,opacity .2s}
.px-faq summary .px-faq__m::before{width:11px;height:2px}
.px-faq summary .px-faq__m::after{width:2px;height:11px}
.px-faq details[open] summary .px-faq__m::after{transform:translate(-50%,-50%) rotate(90deg);opacity:0}
.px-faq details[open] summary .px-faq__m{background:var(--aqua-ink)}
.px-faq details[open] summary .px-faq__m::before{background:#fff}
.px-faq summary:hover .px-faq__m{background:var(--sky-line)}
.px-faq details[open] summary:hover .px-faq__m{background:var(--navy)}
.px-faq summary:hover{color:var(--aqua-ink)}
.px-faq summary:focus-visible{outline:3px solid var(--aqua);outline-offset:3px;border-radius:4px}
.px-faq__a{padding:0 48px 26px 0}
.px-faq__a p{font:400 17px/1.76 var(--fb);color:var(--slate);margin:0 0 16px}
.px-faq__a p:last-child{margin-bottom:0}
.px-faq__a a{color:var(--aqua-ink);font-weight:600;
  border-bottom:1px solid var(--sky-line);text-decoration:none}
.px-faq__a ul{margin:0 0 16px;padding:0;list-style:none}
.px-faq__a li{position:relative;padding:5px 0 5px 22px;
  font:400 16.5px/1.64 var(--fb);color:var(--slate)}
.px-faq__a li::before{content:"";position:absolute;left:2px;top:14px;
  width:7px;height:7px;border-radius:50%;background:var(--aqua)}
@media (max-width:600px){
  .px-faq summary{font-size:17px;padding:20px 0}
  .px-faq__a{padding-right:30px}
}

/* ---- related service cards ----------------------------------------------- */
.px-rel{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,270px),1fr));gap:22px}
.px-rel__c{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);
  border-radius:var(--rc);padding:28px 26px 24px;text-decoration:none;
  box-shadow:var(--sh-card);transition:transform .24s,box-shadow .24s,border-color .24s}
.px-rel__c:hover{transform:translateY(-4px);box-shadow:var(--sh-hover);border-color:var(--aqua)}
.px-rel__c h3{font:700 18.5px/1.3 var(--fh);color:var(--navy);margin:0 0 9px;letter-spacing:-.01em}
.px-rel__c p{font:400 15.8px/1.64 var(--fb);color:var(--slate);margin:0 0 18px;flex:1}
.px-rel__go{display:inline-flex;align-items:center;gap:8px;
  font:700 14px/1 var(--fh);color:var(--aqua-ink);text-transform:uppercase;letter-spacing:.08em}
.px-rel__go svg{width:11px;height:11px;transition:transform .22s}
.px-rel__c:hover .px-rel__go svg{transform:translateX(5px)}
.px-sec--sky .px-rel__c{border-color:var(--sky-line)}

/* ---- coverage / suburb pills --------------------------------------------- */
.px-pills{display:flex;flex-wrap:wrap;gap:10px;list-style:none;margin:0;padding:0}
.px-pills li{margin:0}
.px-pills a,.px-pills span{display:inline-flex;align-items:center;min-height:38px;
  padding:9px 16px;border-radius:999px;background:#fff;border:1px solid var(--line);
  font:600 15px/1 var(--fb);color:var(--ink);text-decoration:none;transition:all .2s}
.px-pills a:hover{border-color:var(--aqua);color:var(--aqua-ink);background:var(--sky)}
.px-pills span{color:var(--slate)}
.px-sec--sky .px-pills a,.px-sec--sky .px-pills span{border-color:var(--sky-line)}
.px-sec--dark .px-pills a,.px-sec--deep .px-pills a{background:rgba(220,239,244,.07);
  border-color:var(--line-dk);color:var(--ondark)}
.px-sec--dark .px-pills a:hover,.px-sec--deep .px-pills a:hover{background:rgba(0,194,222,.16);
  border-color:var(--aqua);color:#fff}

/* ---- callout ------------------------------------------------------------- */
.px-call{display:flex;gap:20px;align-items:flex-start;background:var(--sky);
  border:1px solid var(--sky-line);border-radius:var(--rc);padding:28px 30px;max-width:900px}
.px-call__ico{flex:none;display:inline-flex;align-items:center;justify-content:center;
  width:40px;height:40px;border-radius:11px;background:#fff;color:var(--aqua-ink);
  box-shadow:inset 0 0 0 1px var(--sky-line)}
.px-call__ico svg{width:19px;height:19px}
.px-call h3{font:700 18px/1.3 var(--fh);color:var(--navy);margin:0 0 7px}
.px-call p{font:400 16.5px/1.68 var(--fb);color:var(--ink);margin:0}
.px-call a{color:var(--aqua-ink);font-weight:600;border-bottom:1px solid var(--aqua-ink);
  text-decoration:none}
@media (max-width:600px){.px-call{padding:24px 22px;gap:16px}}

/* ---- surface / type grid ------------------------------------------------- */
.px-surf{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,246px),1fr));gap:24px}
.px-surf__c{position:relative;padding:30px 26px 26px;background:#fff;
  border:1px solid var(--line);border-radius:var(--rc)}
.px-surf__ico{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;
  border-radius:13px;background:rgba(0,194,222,.1);color:var(--aqua-ink);margin-bottom:18px}
.px-surf__ico svg{width:24px;height:24px}
.px-surf__c h3{font:700 18.5px/1.28 var(--fh);color:var(--navy);margin:0 0 9px;letter-spacing:-.01em}
.px-surf__c p{font:400 16px/1.68 var(--fb);color:var(--slate);margin:0}
.px-sec--sky .px-surf__c{border-color:var(--sky-line)}
.px-sec--sky .px-surf__c p{color:var(--ink)}
.px-sec--dark .px-surf__c,.px-sec--deep .px-surf__c{background:var(--char);
  border-color:var(--line-dk)}
.px-sec--dark .px-surf__c h3,.px-sec--deep .px-surf__c h3{color:#fff}
.px-sec--dark .px-surf__c p,.px-sec--deep .px-surf__c p{color:var(--ondark-mute)}
.px-sec--dark .px-surf__ico,.px-sec--deep .px-surf__ico{background:rgba(0,194,222,.17);
  color:var(--aqua-lite)}

/* ---- split: copy beside an image ---------------------------------------- */
.px-split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:62px;align-items:center}
.px-split--flip .px-split__art{order:-1}
.px-split__art figure{margin:0;border-radius:var(--rc);overflow:hidden;
  border:1px solid var(--line);box-shadow:var(--sh)}
.px-split__art img{display:block;width:100%;height:auto}
@media (max-width:980px){
  .px-split{grid-template-columns:minmax(0,1fr);gap:38px}
  .px-split--flip .px-split__art{order:0}
}

/* ---- key figures row ----------------------------------------------------- */
.px-keys{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));
  gap:28px 24px;list-style:none;margin:0;padding:0}
.px-keys li{padding-left:20px;border-left:3px solid var(--aqua)}
.px-keys b{display:block;font:800 clamp(26px,2.5vw,34px)/1.1 var(--fh);
  color:var(--navy);letter-spacing:-.02em;margin-bottom:7px}
.px-keys span{font:400 15.5px/1.56 var(--fb);color:var(--slate)}
.px-sec--dark .px-keys b,.px-sec--deep .px-keys b{color:#fff}
.px-sec--dark .px-keys span,.px-sec--deep .px-keys span{color:var(--ondark-mute)}
.px-sec--sky .px-keys span{color:var(--ink)}

/* ---- status note (honest, non-badge) ------------------------------------- */
.px-note{max-width:900px;padding:20px 24px;background:var(--sky);
  border:1px dashed var(--sky-line);border-radius:var(--r);
  font:400 15.5px/1.68 var(--fb);color:var(--ink)}
.px-note strong{font-weight:700;color:var(--navy)}

/* ==========================================================================
   INTERNAL PAGES - accessibility corrections, scoped to .px-int
   The approved homepage carries no .px-int class, so nothing below changes it.
   Three measured conditions in the v6 CSS are corrected here so they are not
   carried onto the pages built after it. Each is recorded in the handoff.
   ========================================================================== */

/* V6-1  --aqua-ink #047E8F measures 4.35 on --sky #E6F7FB and needs 4.5 for
         small text. #047A8B is a 3 percent darken: 4.58 on sky, 5.05 on white. */
.px-int{--aqua-ink:#047A8B}

/* V6-2  .px-band__p measures 4.35 at 390px over the photograph. The scrim is
         deepened on the narrow layout only, where the copy sits over the
         busiest part of the image. */
@media (max-width:600px){
  .px-int .px-band__scrim{background:linear-gradient(95deg,
    rgba(5,24,34,.94) 0%,rgba(5,24,34,.86) 42%,rgba(5,24,34,.7) 72%,rgba(5,24,34,.82) 100%)}
}

/* V6-10 a long place name in the .px-answer__k label overflows its 120px box
          on the narrow layout. Location pages put "SUBURB, COUNCIL" there, and
          Camberwell, Boroondara is wider than the box. Allowed to break. */
.px-int .px-answer__k{overflow-wrap:anywhere;hyphens:auto}

/* V6-9  .px-band__p measures 4.45 over the brighter photographs at desktop
         widths, just under the 4.5 AA threshold. The two lightest stops of the
         scrim are deepened from 601px up, where the copy sits over the right
         hand side of the image. Below 601px the V6-2 rule above already
         handles it, so this is scoped above it rather than overriding it. */
@media (min-width:601px){
  .px-int .px-band__scrim{background:linear-gradient(95deg,
    rgba(5,24,34,.9) 0%,rgba(5,24,34,.74) 42%,rgba(5,24,34,.52) 72%,rgba(5,24,34,.68) 100%)}
}

/* V6-3  the two 500x500 photographs upscale past 1.0x above 500 CSS px, so
         internal pages cap any figure that carries one. */
.px-int .px-fig--small img{max-width:500px;margin:0 auto}

/* V6-5  at 320px the chevron inside a wrapped .px-btn--cta leaves the button
         box. Allowing the label and chevron to wrap together fixes it. */
@media (max-width:360px){
  .px-int .px-btn,.px-int .pe-btn{flex-wrap:wrap;row-gap:2px}
}

/* V6-8  --slate #5A7684 measures 4.37 on --sky #E6F7FB and needs 4.5 for normal
         text, so any body copy on a sky band fails. Rather than chase each
         selector, --slate is redefined inside sky surfaces on internal pages:
         #577280 is a 3 percent darken that measures 4.62 on sky and 5.09 on
         white, so nothing else shifts perceptibly. Same for the quote panel's
         step list, which also sits on sky. */
.px-int .px-sec--sky,.px-int .pe-qsteps{--slate:#577280}
.px-int .px-sec--sky .px-head .px-h2+.px-lede{color:var(--ink)}
.px-int .pe-qsteps li{color:var(--ink)}

/* ---- wide statement hero: no art column, copy centred over a scrim -------- */
.px-ihero--wide .px-ihero__in{grid-template-columns:minmax(0,1fr);justify-items:center;
  text-align:center;padding:96px var(--gut) 100px;
  max-width:calc(980px + var(--gut) * 2);margin:0 auto}
.px-ihero--wide .px-ihero__lede{max-width:62ch;margin-left:auto;margin-right:auto}
.px-ihero--wide .px-ihero__cta{justify-content:center}
.px-ihero--wide .px-ihero__facts{justify-content:center;gap:12px 36px}
.px-ihero--wide .px-ihero__scrim{background:
  linear-gradient(180deg,rgba(7,36,51,.9) 0%,rgba(7,36,51,.8) 40%,rgba(11,46,64,.92) 100%)}
.px-ihero__kick{display:inline-flex;align-items:center;gap:11px;margin:0 0 20px;
  padding:8px 16px;border-radius:999px;background:rgba(0,194,222,.14);
  border:1px solid var(--line-dk);font:700 12.5px/1 var(--fh);
  letter-spacing:.14em;text-transform:uppercase;color:var(--aqua-lite)}
.px-ihero__kick svg{width:15px;height:15px}
@media (max-width:1000px){.px-ihero--wide .px-ihero__in{padding:66px var(--gut) 70px}}
@media (max-width:600px){.px-ihero--wide .px-ihero__in{padding:50px var(--gut) 54px}
  .px-ihero--wide .px-ihero__facts{gap:10px 20px}}


/* ---- card grid column control -------------------------------------------- */
.px-rel--3,.px-fact--3,.px-surf--3{grid-template-columns:repeat(auto-fit,minmax(min(100%,318px),1fr))}
.px-rel--2,.px-fact--2,.px-surf--2{grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr))}
@media (min-width:1101px){
  .px-rel--3,.px-fact--3,.px-surf--3{grid-template-columns:repeat(3,minmax(0,1fr))}
  .px-rel--2,.px-fact--2,.px-surf--2{grid-template-columns:repeat(2,minmax(0,1fr))}
  .px-rel--4{grid-template-columns:repeat(4,minmax(0,1fr))}
}

/* ---- routing card: description, then what the family covers --------------- */
.px-rel__c .px-rel__ico{display:inline-flex;align-items:center;justify-content:center;
  width:42px;height:42px;border-radius:12px;background:rgba(0,194,222,.1);
  color:var(--aqua-ink);margin-bottom:17px}
.px-rel__c .px-rel__ico svg{width:21px;height:21px}
.px-rel__covers{margin:0 0 18px;padding-top:14px;border-top:1px solid var(--line);
  font:400 14.6px/1.6 var(--fb);color:var(--ink);flex:none}
.px-rel__covers b{display:block;font:800 11.5px/1 var(--fh);letter-spacing:.13em;
  text-transform:uppercase;color:var(--slate);margin-bottom:7px}
.px-sec--sky .px-rel__covers{border-top-color:var(--sky-line)}

/* ---- answer block: tighter key column ------------------------------------ */
.px-answer__k{padding-top:9px;border-top:3px solid var(--aqua);letter-spacing:.1em}

/* V7-01  The answer block ran a narrow key column beside the body, so its body
   copy began 192px right of the content edge. It was then the one block on the
   page not sitting on the grid every other block uses, which is what read as a
   misalignment. The stacked treatment the component already used below 900px is
   now used at every width: the label keeps its rule and its measure and sits
   above the copy, and the copy starts on the content edge like everything else.
   No paragraph was ever flowing into the key column; that was measured across
   all 143 blocks at four desktop widths before this was changed. */
.px-answer{grid-template-columns:minmax(0,1fr);gap:18px}
.px-answer__k{max-width:260px}
@media (max-width:900px){.px-answer{gap:16px}
  .px-answer__k{max-width:200px}}

/* ---- child index: used where a family has more children than a card grid
       can lay out cleanly. Denser, scannable, and a different rhythm from the
       routing cards on the services hub. ---------------------------------- */
.px-index{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 48px;
  border-top:1px solid var(--line)}
.px-index a{display:grid;grid-template-columns:1fr auto;align-items:start;gap:10px 18px;
  padding:22px 2px 20px;border-bottom:1px solid var(--line);text-decoration:none;
  transition:padding-left .22s,border-color .22s}
.px-index a:hover{padding-left:12px;border-bottom-color:var(--aqua)}
.px-index b{grid-column:1;font:700 18px/1.3 var(--fh);color:var(--navy);letter-spacing:-.01em}
.px-index span{grid-column:1;font:400 15.6px/1.6 var(--fb);color:var(--slate)}
.px-index svg{grid-column:2;grid-row:1/3;width:13px;height:13px;color:var(--aqua-ink);
  margin-top:6px;transition:transform .22s}
.px-index a:hover svg{transform:translateX(5px)}
.px-index a:hover b{color:var(--aqua-ink)}
.px-sec--sky .px-index,.px-sec--sky .px-index a{border-color:var(--sky-line)}
.px-sec--sky .px-index span{color:var(--ink)}
.px-sec--dark .px-index,.px-sec--deep .px-index,
.px-sec--dark .px-index a,.px-sec--deep .px-index a{border-color:var(--line-dk)}
.px-sec--dark .px-index b,.px-sec--deep .px-index b{color:#fff}
.px-sec--dark .px-index span,.px-sec--deep .px-index span{color:var(--ondark-mute)}
.px-sec--dark .px-index svg,.px-sec--deep .px-index svg{color:var(--aqua-lite)}
.px-sec--dark .px-index a:hover b,.px-sec--deep .px-index a:hover b{color:var(--aqua-lite)}
@media (max-width:860px){.px-index{grid-template-columns:minmax(0,1fr);gap:0}}

/* ---- area blocks: a region or service with its heading and a pill set ----- */
.px-areas2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:48px 56px}
.px-areablock h3{display:flex;flex-wrap:wrap;align-items:baseline;gap:12px;margin:0 0 10px}
.px-areablock h3 span{font:700 12.5px/1 var(--fh);letter-spacing:.12em;text-transform:uppercase;
  color:var(--aqua-ink);padding:5px 10px;border-radius:999px;background:rgba(0,194,222,.1)}
.px-areablock p{font:400 16.4px/1.68 var(--fb);color:var(--slate);margin:0 0 20px;max-width:56ch}
.px-sec--sky .px-areablock p{color:var(--ink)}
.px-sec--dark .px-areablock p,.px-sec--deep .px-areablock p{color:var(--ondark-mute)}
.px-sec--dark .px-areablock h3 span,.px-sec--deep .px-areablock h3 span{
  color:var(--aqua-lite);background:rgba(0,194,222,.17)}
@media (max-width:900px){.px-areas2{grid-template-columns:minmax(0,1fr);gap:40px}}

/* ==========================================================================
   V3 alignment and consistency pass. Shared corrections only: every rule here
   fixes a component that several pages carry, so no page needs its own CSS.
   None of these selectors appears on the approved home page.
   ========================================================================== */

/* V6-14  A four item key row or process strip fell to three columns between the
   phone and desktop breakpoints, which left the fourth item alone next to an
   empty cell. Four wraps as two by two. The quantity query means a three item
   row is untouched, and a browser without :has() simply keeps today's layout. */
@media (min-width:601px) and (max-width:999px){
  .px-keys:has(> :nth-child(4)):not(:has(> :nth-child(5))),
  .px-proc:has(> :nth-child(4)):not(:has(> :nth-child(5))){
    grid-template-columns:repeat(2,minmax(0,1fr))
  }
}
/* and five items wrap three plus two rather than four plus one */
@media (min-width:601px) and (max-width:1193px){
  .px-keys:has(> :nth-child(5)):not(:has(> :nth-child(6))){
    grid-template-columns:repeat(3,minmax(0,1fr))
  }
}
/* six never fits across a 1152px content column, so it always stranded the
   sixth item on a row of its own. Three and three, at every width above the
   phone layout. */
@media (min-width:601px){
  .px-keys:has(> :nth-child(6)):not(:has(> :nth-child(7))){
    grid-template-columns:repeat(3,minmax(0,1fr))
  }
}

/* V6-18  A key row is a grid, but each item laid its own heading and its own
   description out independently, so a heading that wrapped to two lines pushed
   its description below the ones beside it. Subgrid puts every heading on one
   row and every description on the next. */
.px-keys li{display:grid;grid-template-rows:subgrid;grid-row:span 2;align-content:start}
/* the region blocks go out of step the same way when one heading wraps */
@media (min-width:901px){
  .px-areablock{display:grid;grid-template-rows:subgrid;grid-row:span 3;
    row-gap:0;align-content:start}
}

/* V6-20  Same fault as V6-18, in the card components. Each card laid itself
   out independently, so one heading wrapping to a second line pushed that
   card's paragraph below its neighbours' and the row read ragged. Subgrid puts
   every heading in one row and every paragraph in the next, and costs nothing
   on a row where no heading wraps. row-gap is zeroed so the grid's own gutter
   does not reappear inside a card. */
@media (min-width:601px){
  .px-fact__c{display:grid;grid-template-rows:subgrid;grid-row:span 2;
    row-gap:0;align-content:start}
  .px-surf__c,.px-proc__s{display:grid;grid-template-rows:subgrid;grid-row:span 3;
    row-gap:0;align-content:start}
  /* the plain routing card is heading, description, link; the richer variant
     carries an icon and a covers line as well, so each takes its own row count */
  .px-rel__c:not(:has(> .px-rel__ico)){display:grid;grid-template-rows:subgrid;
    grid-row:span 3;row-gap:0;align-content:start}
  .px-rel__c:has(> .px-rel__ico){display:grid;grid-template-rows:subgrid;
    grid-row:span 5;row-gap:0;align-content:start}
  .px-rel__c p{flex:none}
}

/* V6-21  The child index puts a title and its one line description in a two
   column list. A title that wrapped pushed its own description down while the
   entry beside it stayed put. Same subgrid treatment. */
@media (min-width:601px){
  .px-index a{grid-template-rows:subgrid;grid-row:span 2;row-gap:0}
  .px-index b{margin-bottom:10px}
}

/* V6-19  The review note is the last thing in its section everywhere except
   the two legal pages, where prose follows it immediately and the first
   heading sat on the panel's own border. */
.px-note + *{margin-top:34px}
.px-pills + .px-note,.px-tbl + .px-note,ul + .px-note,table + .px-note{margin-top:34px}

/* V6-23  A two word place name was being split across two lines of the hero
   heading, so a suburb read as "Box" over "Hill", and section headings left
   109 two and three letter widows across the site. Measured across every
   heading at six widths: pretty wrapping on the hero leaves no place name
   split and no short first line, balanced wrapping on the section headings
   removes every widow, and neither adds a line anywhere. */
.px-ihero h1{text-wrap:pretty}
/* and the same on internal section headings, which removed 109 two and three
   letter widows across the site without changing a line count */
.px-int .px-h2,.px-int .px-band__h{text-wrap:balance}
/* and the ledes under them wrap without leaving one word on a line */
.px-int .px-lede,.px-ihero__lede,.px-int .px-band__sub{text-wrap:pretty}

/* V6-22  The eyebrow is rendered in title case by the stylesheet. CSS
   capitalize uppercases the letter after a hyphen as well, which turned the
   council name Merri-bek into Merri-Bek. A single hyphenated word is left in
   the case the data supplies it in. */
.px-eyebrow--asis{text-transform:none}

/* V6-24  A link on a dark surface was lifted to the light aqua inside prose
   only, so an inline link in a key row or a card kept the on-light colour and
   measured about 1.6 against the dark panel. The lift now covers every inline
   link on a dark or deep surface; buttons and pills set their own colour. */
.px-sec--dark a:not([class]),.px-sec--deep a:not([class]),
.px-band a:not([class]){color:var(--aqua-lite)}

/* V6-17  The council count badge sits in the region heading as a flex item, so
   on a heading short enough to leave room it stayed on the first line while its
   neighbours pushed it to a second. Two blocks side by side then ran a line out
   of step all the way down. The badge always takes a line of its own.

   V6-30  The basis that claims the line was also sizing the pill, so the badge
   drew as a full width bar with its label stranded at the far left. It claims
   the line and is then clamped back to its own text. */
.px-areablock h3 span{flex-basis:100%;max-width:max-content}

/* V6-15  The comparison table is given a minimum width below 720px and scrolls
   inside its own box. Its caption was being laid out at that same minimum, so
   the sentence ran off the visible area and could only be read by scrolling a
   table sideways. Pinning it to the scroll origin keeps it readable. */
@media (max-width:720px){
  .px-cmp caption{position:sticky;left:0;
    width:calc(100vw - (var(--gut) * 2) - 2px)}
}

/* V6-16  The quote form puts Suburb and Service side by side in equal halves,
   and the longest service name is wider than half the form, so a pre-selected
   value was cut off mid word. Service takes the larger share of the row. */
@media (min-width:621px){
  .px-form .px-field--svc{grid-template-columns:minmax(0,.46fr) minmax(0,1fr)}
}

/* ==========================================================================
   V3.1  THE STANDARD ENQUIRY FORM IN ITS THREE CONTEXTS
   One component, three widths. The markup is identical everywhere; only the
   container differs, so there is one form system rather than three.
   ========================================================================== */

/* V6-25  In the floating panel the step bar and the form supply their own
   padding. Inside a page panel the panel already has padding, so they do not. */
.px-form--steps{padding:36px 40px 40px}
.px-hform__body .pe-qsteps{padding:0 0 16px;margin-bottom:20px}
.px-hform__body .pe-qform{padding:0}
.px-form .pe-qsteps,.px-hform .pe-qsteps{padding:0 0 18px;margin:0 0 24px;
  background:none;border-bottom:1px solid var(--line)}
.px-form .pe-qform,.px-hform .pe-qform{padding:0;flex:none}
.px-form .pe-qnav,.px-hform .pe-qnav{margin-top:26px;padding-top:0}

/* a narrow panel stacks the two up row rather than halving a 250px column */
.pe-qform--compact .pe-field--row{grid-template-columns:minmax(0,1fr);gap:0}
.pe-qform--compact .pe-field--row>div{margin-bottom:18px}
.pe-qform--compact .pe-field--row>div:last-child{margin-bottom:0}

/* V6-26  Get a Quote and Contact exist to carry this form, so it runs across
   the page instead of sitting in a sidebar column. */
.px-quote--wide .px-quote__grid{grid-template-columns:minmax(0,1fr);gap:46px;
  justify-items:center}
.px-quote--wide .px-quote__intro{max-width:760px;text-align:center}
.px-quote--wide .px-form--wide{width:100%;max-width:780px;padding:44px 48px 48px}
/* The step list is built as a narrow vertical column: a connector line down
   the side, cards indented to clear a number that straddles their left edge.
   Across a row the connector goes, the indent goes, and the number sits inside
   the card above the text, so each step has the whole column to read in. */
.px-steps--row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;
  margin-top:44px;text-align:left}
.px-steps--row::before{display:none}
.px-steps--row li{padding:26px 26px 24px;margin:0}
.px-steps--row li+li{margin-top:0}
.px-steps--row li:hover{transform:none}
.px-steps--row li::before{position:static;margin:0 0 16px;display:flex;
  align-items:center;justify-content:center;line-height:1}
@media (max-width:900px){
  .px-steps--row{grid-template-columns:minmax(0,1fr);gap:0}
  .px-quote--wide .px-form--wide{padding:32px 26px 36px}
}

/* V6-27  The invalid state was only drawn on an input, so a select or a
   textarea that failed validation looked no different from a valid one. */
.pe-qform input.is-bad,.pe-qform select.is-bad,.pe-qform textarea.is-bad,
.pe-qform .pe-qchips.is-bad span{border-color:#B4232A}
.pe-qform .is-bad:focus{border-color:#B4232A;box-shadow:0 0 0 4px rgba(180,35,42,.14)}
.pe-qerr{display:block;margin-top:7px;font:600 13px/1.5 var(--fb);color:#B4232A}
.pe-qerr:empty{display:none}

/* V6-28  Three labelled steps do not fit across a phone, so each label wrapped
   to two lines. The step in hand keeps its label and the others show their
   number, which is the usual pattern and stays on one line. */
@media (max-width:560px){
  .pe-qsteps{gap:10px}
  .pe-qsteps li{flex:0 0 auto}
  .pe-qsteps li.is-on{flex:1 1 auto}
  .pe-qsteps li:not(.is-on){font-size:0}
  .pe-qsteps li:not(.is-on) span{font:800 11.5px/1 var(--fh)}
}

/* V6-29  The comparison table is a horizontal scroller below 720px (V6-15), but
   it gave no sign of it: the last column was simply cut off at the viewport
   edge, often mid word, and nothing told a phone visitor there was more to the
   right. Every page carrying a table hid 208px of it at 390px. The scroll stays
   as it was; what is added is the affordance. A fade over the right edge says
   the content continues, and a line under the table says how to reach it. Both
   are drawn only while something is actually hidden, so a table that fits is
   untouched at every width. */
.px-cmp__box{position:relative}
.px-cmp__box::after{content:"";position:absolute;top:0;right:0;width:34px;bottom:0;
  pointer-events:none;opacity:0;transition:opacity .18s ease;
  background:linear-gradient(to left,rgba(10,43,60,.22),rgba(10,43,60,0))}
.px-cmp.is-over:not(.is-end) .px-cmp__box::after{opacity:1}
.px-cmp__hint{display:none;margin:10px 0 0;
  font:600 13.5px/1.5 var(--fb);color:var(--slate)}
.px-cmp__hint::after{content:"\00a0\2192";font-weight:700;color:var(--aqua-ink)}
.px-cmp.is-over .px-cmp__hint{display:block}

/* V7-02  A call-out box had no spacing rule against anything placed next to it,
   so wherever one sat directly beside another block the two ran together with
   nothing between them: against a key row, a card grid, a prose block and a
   copy-and-image split, all at zero. The separation is set on the adjacency
   itself rather than with a spacer element, so it applies wherever a call-out
   meets a neighbour and nowhere else. Direct children of the content wrapper
   only, so a call-out inside a grid or a card keeps that container's own
   spacing. */
.px-wrap > .px-call + *,
.px-wrap > * + .px-call{margin-top:38px}
@media (max-width:600px){
  .px-wrap > .px-call + *,
  .px-wrap > * + .px-call{margin-top:30px}
}

/* V7-08  Validation messages are written under the control rather than left to
   the browser's own bubble, so the message stays on screen while the field is
   being fixed and every enquiry form behaves the same way. From Homepage V7. */
.fv-msg{display:none;align-items:flex-start;gap:6px;margin:7px 0 0;
  font:600 13.5px/1.45 var(--fb);color:#C8323A}
.fv-msg svg{flex:none;width:15px;height:15px;margin-top:1px;color:#C8323A}
.fv-msg.fv-show{display:flex}
.px-form input.fv-bad,.px-form select.fv-bad,.px-form textarea.fv-bad,
.px-hform input.fv-bad,.px-hform select.fv-bad,.px-hform textarea.fv-bad,
.pe-qform input.fv-bad,.pe-qform select.fv-bad,.pe-qform textarea.fv-bad,
input.fv-bad,select.fv-bad,textarea.fv-bad{border-color:#C8323A;
  box-shadow:0 0 0 3px rgba(200,50,58,.12)}
.pe-qchips.fv-bad{outline:1px solid #C8323A;outline-offset:5px;border-radius:10px}
input.fv-ok,select.fv-ok,textarea.fv-ok{border-color:rgba(0,178,201,.55)}

/* V8-02  A link on a dark band needs the light aqua, which was being set with
   an inline style attribute. Inline styles are not wanted in the delivered
   markup, so it is a class. */
.px-ondark-link{color:var(--aqua-lite)}

/* V8-03  Three more sets of values were carried in style attributes on the
   elements themselves. The footer's second paragraph is reached by its position
   rather than by a new class, so the approved footer markup is untouched; the
   five locator pins get a class each. Same values, so nothing moves. */
.pe-foot__grid p + p{margin-top:18px}
.px-pin--north{left:50%;top:20%}
.px-pin--base{left:41%;top:31%}
.px-pin--west{left:23%;top:50%}
.px-pin--inner{left:47%;top:61%}
.px-pin--east{left:75%;top:48%}

