/* ============================================================
   Per-page-type hero variants (appended after the base system)
   ============================================================ */

/* --- SERVICE HERO: centered copy + full-width banner (distinct from the homepage split) --- */
.px-hero--center{padding-bottom:0}
.px-hero--center .px-hero__grid{grid-template-columns:minmax(0,1fr);text-align:center;padding-bottom:46px;gap:0}
.px-hero--center .px-hero__copy{max-width:820px;margin:0 auto}
.px-hero--center .px-eyebrow{justify-content:center}
.px-hero--center nav[aria-label="Breadcrumb"]{text-align:center}
.px-hero--center .px-hero__cta{justify-content:center}
.px-hero--center .px-hero__copy>ul{justify-content:center}
.px-hero__banner{max-width:var(--max);margin:0 auto;padding:0 var(--gut) 8px}
.px-hero__banner figure{margin:0;border-radius:var(--rc);overflow:hidden;aspect-ratio:16/6;
  box-shadow:0 34px 80px -34px rgba(0,0,0,.72);
  clip-path:polygon(0 0,100% 0,100% 100%,0 calc(100% - 30px))}
.px-hero__banner img{width:100%;height:100%;object-fit:cover}
@media (max-width:820px){.px-hero__banner figure{aspect-ratio:16/9}}

/* --- LOCATION HERO: brighter background, dark text --- */
.px-hero--light{background:linear-gradient(162deg,#ECF8FA 0%,#D7EEF2 58%,#C7E4EA 100%);color:var(--ink)}
.px-hero--light .px-hero__scrim,
.px-hero--light .px-hero__grain,
.px-hero--light::before,
.px-hero--light::after{display:none!important}
.px-hero--light h1{color:var(--navy)}
.px-hero--light .px-eyebrow{color:var(--aqua-ink)}
.px-hero--light .px-eyebrow::before{background:var(--aqua)}
.px-hero--light .px-hero__lede{color:var(--slate)}
.px-hero--light .px-hero__vh{color:var(--aqua-ink)!important}
.px-hero--light .px-hero__crumb{color:var(--slate)!important}
.px-hero--light .px-hero__crumb a{color:var(--aqua-ink)!important}
.px-hero--light .px-hero__facts{color:var(--slate)!important}
.px-hero--light .px-hero__art::after{background:linear-gradient(180deg,var(--aqua) 0%,rgba(0,178,201,0) 100%)}
.px-hero--light .px-btn--ondark{color:var(--navy);box-shadow:inset 0 0 0 2px rgba(14,39,51,.22);background:transparent}
.px-hero--light .px-btn--ondark:hover{box-shadow:inset 0 0 0 2px var(--navy)}

/* --- Prominent logo placeholder in the header --- */
.pe-brand{display:flex;align-items:center;flex:0 0 auto}
.pe-brand .pe-logo-ph{height:clamp(72px,6.5vw,104px);width:auto;border-radius:10px;display:block}
.pe-head__bar{align-items:center;gap:16px;flex-wrap:nowrap}
@media (max-width:820px){.pe-brand .pe-logo-ph{height:72px}}
